import { useNavigate } from 'react-router-dom';
import { Box, Container, Typography, Card, CardContent, CardMedia, Rating, IconButton, CircularProgress } from '@mui/material';
import { useEffect, useState } from 'react';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';
import ShoppingCartOutlinedIcon from '@mui/icons-material/ShoppingCartOutlined';
import Navbar from '../WrapperComponents/Navbar';
import Footer from '../WrapperComponents/Footer';
import { ProductService } from '../../services/api';

const AllProducts = () => {
    const navigate = useNavigate();
    const [products, setProducts] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchProducts = async () => {
            try {
                const { data } = await ProductService.getAll();
                // Handle both old array format and new paginated format
                if (Array.isArray(data)) {
                    setProducts(data);
                } else if (data.products) {
                    setProducts(data.products);
                } else {
                    setProducts([]);
                }
            } catch (error) {
                console.error("Error fetching products:", error);
                setProducts([]);
            } finally {
                setIsLoading(false);
            }
        };
        fetchProducts();
    }, []);

    return (
        <Box sx={{ bgcolor: 'white', minHeight: '100vh' }}>
            <Navbar />

            <Container maxWidth="xl" sx={{ mt: 4, mb: 8 }}>
                <Box sx={{ mb: 4 }}>
                    <Typography variant="h4" sx={{ fontWeight: 800, mb: 1 }}>
                        All Products
                    </Typography>
                    <Typography variant="body1" sx={{ color: 'text.secondary' }}>
                        Discover our complete collection of premium products
                    </Typography>
                </Box>

                {isLoading ? (
                    <Box sx={{ display: 'flex', justifyContent: 'center', py: 10 }}>
                        <CircularProgress sx={{ color: 'black' }} />
                    </Box>
                ) : (
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 3, justifyContent: 'center' }}>
                        {products.map((product) => (
                            <Box
                                key={product._id}
                                sx={{
                                    width: { xs: '100%', sm: 'calc(50% - 24px)', md: 'calc(33.33% - 24px)', lg: 'calc(25% - 24px)' },
                                    mb: 2
                                }}
                            >
                                <Card
                                    onClick={() => navigate(`/product/${product._id}`)}
                                    sx={{
                                        border: 'none',
                                        boxShadow: 'none',
                                        bgcolor: '#f8f9fa',
                                        borderRadius: 4,
                                        p: 2,
                                        cursor: 'pointer',
                                        height: '420px',
                                        display: 'flex',
                                        flexDirection: 'column',
                                        transition: 'transform 0.3s ease',
                                        '&:hover': {
                                            transform: 'translateY(-8px)',
                                            bgcolor: '#f1f3f5',
                                        },
                                        '&:hover .product-image': {
                                            transform: 'scale(1.02)',
                                        },
                                    }}
                                >
                                    <Box sx={{ position: 'relative', borderRadius: 4, overflow: 'hidden', mb: 2, pt: '100%', width: '100%' }}>
                                        <CardMedia
                                            component="img"
                                            image={product.images?.[0] || 'https://via.placeholder.com/400'}
                                            alt={product.title}
                                            className="product-image"
                                            sx={{
                                                position: 'absolute',
                                                top: 0,
                                                left: 0,
                                                width: '100%',
                                                height: '100%',
                                                transition: 'transform 0.5s ease',
                                                bgcolor: '#f5f5f5',
                                                objectFit: 'cover',
                                            }}
                                        />
                                        <IconButton
                                            sx={{
                                                position: 'absolute',
                                                top: 10,
                                                right: 10,
                                                bgcolor: 'white',
                                                '&:hover': { bgcolor: 'white', color: '#e91e63' },
                                            }}
                                            size="small"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                            }}
                                        >
                                            <FavoriteBorderIcon fontSize="small" />
                                        </IconButton>
                                    </Box>

                                    <CardContent sx={{ p: 1, flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                                        <Typography variant="caption" sx={{ color: 'text.secondary', display: 'block', mb: 0.5, textTransform: 'uppercase' }}>
                                            {product.category}
                                        </Typography>
                                        <Typography
                                            variant="subtitle1"
                                            sx={{
                                                fontWeight: 'bold',
                                                fontSize: '1.1rem',
                                                mb: 0.5,
                                                height: '2.6em',
                                                overflow: 'hidden',
                                                textOverflow: 'ellipsis',
                                                display: '-webkit-box',
                                                WebkitLineClamp: 2,
                                                WebkitBoxOrient: 'vertical',
                                                lineHeight: '1.3em'
                                            }}
                                        >
                                            {product.title}
                                        </Typography>

                                        <Box sx={{ mt: 'auto' }}>
                                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                                <Rating value={product.rating || 0} readOnly size="small" sx={{ color: '#ffb400', mr: 0.5 }} />
                                                <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                                    ({product.numReviews || 0})
                                                </Typography>
                                            </Box>
                                            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                                <Box>
                                                    <Typography variant="h6" sx={{ fontWeight: 800, fontSize: '1.3rem' }}>
                                                        Ôé╣{(Number(product?.price ?? product?.pricePerUnit ?? 0) || 0).toLocaleString('en-IN')}
                                                    </Typography>
                                                </Box>
                                                <IconButton
                                                    sx={{
                                                        bgcolor: '#212121',
                                                        color: 'white',
                                                        '&:hover': { bgcolor: '#424242' },
                                                    }}
                                                    size="small"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                    }}
                                                >
                                                    <ShoppingCartOutlinedIcon fontSize="small" />
                                                </IconButton>
                                            </Box>
                                        </Box>
                                    </CardContent>
                                </Card>
                            </Box>
                        ))}
                    </Box>
                )}

                {!isLoading && products.length === 0 && (
                    <Box sx={{ textAlign: 'center', py: 8 }}>
                        <Typography variant="h5" sx={{ color: 'text.secondary' }}>
                            No products found
                        </Typography>
                    </Box>
                )}
            </Container>

            <Footer />
        </Box>
    );
};

export default AllProducts;

import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Box, Container, Typography, Card, CardContent, CardMedia, Rating, IconButton, CircularProgress, Stack, Button } from '@mui/material';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';
import ShoppingCartOutlinedIcon from '@mui/icons-material/ShoppingCartOutlined';
import Navbar from '../WrapperComponents/Navbar';
import Footer from '../WrapperComponents/Footer';
import { ProductService, CartService } from '../../services/api';

const CategoryPage = () => {
    const { categoryName } = useParams<{ categoryName: string }>();
    const navigate = useNavigate();
    const [products, setProducts] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchCategoryProducts = async () => {
            setIsLoading(true);
            try {
                const { data } = await ProductService.getAll({ category: categoryName });

                // If the backend doesn't filter by query, filter here
                const filtered = data.filter((p: any) =>
                    p.category.toLowerCase() === categoryName?.toLowerCase().replace(/-/g, ' ') ||
                    p.category.toLowerCase().includes(categoryName?.toLowerCase() || '')
                );

                setProducts(filtered);
            } catch (error) {
                console.error("Error fetching category products:", error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchCategoryProducts();
    }, [categoryName]);

    return (
        <Box sx={{ minHeight: '100vh', bgcolor: '#f8fafc', display: 'flex', flexDirection: 'column' }}>
            <Navbar />

            <Container maxWidth="xl" sx={{ flex: 1, py: 6 }}>
                <Box sx={{ mb: 6, textAlign: 'center' }}>
                    <Typography variant="overline" sx={{ color: '#64748b', fontWeight: 800, letterSpacing: 2 }}>
                        COLLECTION
                    </Typography>
                    <Typography variant="h2" sx={{ fontWeight: 900, color: '#0f172a', mb: 2, textTransform: 'capitalize' }}>
                        {categoryName?.replace(/-/g, ' ')}
                    </Typography>
                </Box>

                {isLoading ? (
                    <Box sx={{ display: 'flex', justifyContent: 'center', py: 10 }}>
                        <CircularProgress color="inherit" />
                    </Box>
                ) : products.length > 0 ? (
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 3, justifyContent: 'center' }}>
                        {products.map((product) => (
                            <Box
                                key={product._id}
                                sx={{
                                    width: { xs: '100%', sm: 'calc(50% - 24px)', md: 'calc(33.33% - 24px)', lg: 'calc(25% - 24px)' },
                                    mb: 2
                                }}
                            >
                                <Card
                                    onClick={() => navigate(`/product/${product._id}`)}
                                    sx={{
                                        border: 'none',
                                        boxShadow: 'none',
                                        bgcolor: 'white',
                                        borderRadius: 5,
                                        p: 2,
                                        cursor: 'pointer',
                                        transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                        '&:hover': {
                                            transform: 'translateY(-10px)',
                                            boxShadow: '0 20px 40px rgba(0,0,0,0.05)'
                                        },
                                        '&:hover .product-image': {
                                            transform: 'scale(1.05)',
                                        },
                                    }}
                                >
                                    <Box sx={{ position: 'relative', borderRadius: 4, overflow: 'hidden', mb: 2, pt: '100%', width: '100%' }}>
                                        <CardMedia
                                            component="img"
                                            image={product.images?.[0] || 'https://via.placeholder.com/400'}
                                            alt={product.title}
                                            className="product-image"
                                            sx={{
                                                position: 'absolute',
                                                top: 0,
                                                left: 0,
                                                width: '100%',
                                                height: '100%',
                                                transition: 'transform 0.6s ease',
                                                bgcolor: '#f1f5f9',
                                                objectFit: 'cover',
                                            }}
                                        />
                                        <IconButton
                                            sx={{
                                                position: 'absolute',
                                                top: 15,
                                                right: 15,
                                                bgcolor: 'white',
                                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                                                '&:hover': { bgcolor: 'white', color: '#ef4444' },
                                            }}
                                            size="small"
                                            onClick={(e) => e.stopPropagation()}
                                        >
                                            <FavoriteBorderIcon fontSize="small" />
                                        </IconButton>
                                    </Box>

                                    <CardContent sx={{ p: 1 }}>
                                        <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700, textTransform: 'uppercase' }}>
                                            {product.category}
                                        </Typography>
                                        <Typography
                                            variant="h6"
                                            sx={{
                                                fontWeight: 800,
                                                mt: 0.5,
                                                mb: 1,
                                                height: '2.8rem',
                                                overflow: 'hidden',
                                                display: '-webkit-box',
                                                WebkitLineClamp: 2,
                                                WebkitBoxOrient: 'vertical',
                                                lineHeight: 1.2
                                            }}
                                        >
                                            {product.title}
                                        </Typography>

                                        <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2 }}>
                                            <Rating value={product.rating || 0} readOnly size="small" precision={0.5} />
                                            <Typography variant="caption" sx={{ fontWeight: 600, color: '#64748b' }}>
                                                ({product.numReviews || 0})
                                            </Typography>
                                        </Stack>

                                        <Stack direction="row" alignItems="center" justifyContent="space-between">
                                            <Typography variant="h5" sx={{ fontWeight: 900 }}>
                                                Ôé╣{(Number(product?.price ?? product?.pricePerUnit ?? 0) || 0).toLocaleString('en-IN')}
                                            </Typography>
                                            <IconButton
                                                sx={{
                                                    bgcolor: '#212121',
                                                    color: 'white',
                                                    '&:hover': { bgcolor: 'black' },
                                                    borderRadius: 2
                                                }}
                                                size="small"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    CartService.addToCart({ productId: product._id, quantity: 1 });
                                                }}
                                            >
                                                <ShoppingCartOutlinedIcon fontSize="small" />
                                            </IconButton>
                                        </Stack>
                                    </CardContent>
                                </Card>
                            </Box>
                        ))}
                    </Box>
                ) : (
                    <Box sx={{ textAlign: 'center', py: 10, bgcolor: 'white', borderRadius: 6 }}>
                        <Typography variant="h5" sx={{ color: '#94a3b8', mb: 3, fontWeight: 700 }}>No products found in this category.</Typography>
                        <Button
                            variant="contained"
                            onClick={() => navigate('/retail')}
                            sx={{ bgcolor: 'black', color: 'white', px: 4, py: 1.5, borderRadius: 3, fontWeight: 700 }}
                        >
                            Back to Retail
                        </Button>
                    </Box>
                )}
            </Container>

            <Footer />
        </Box>
    );
};

export default CategoryPage;

import { useState, useEffect } from 'react';
import { Box, Container, Typography, TextField, Button, Paper, Stack, Divider, CircularProgress, IconButton, Radio, RadioGroup, FormControlLabel, FormControl } from '@mui/material';
import { useNavigate, useLocation } from 'react-router-dom';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';
import Navbar from '../WrapperComponents/Navbar';
import Footer from '../WrapperComponents/Footer';
import { CartService, OrderService, PaymentService } from '../../services/api';
import CheckoutForm from '../SpecifiedComponents/Profile/CheckoutForm';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const Checkout = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const [isLoading, setIsLoading] = useState(true);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [cart, setCart] = useState<any>(null);
    const [paymentMethod, setPaymentMethod] = useState(location.state?.preferredPaymentMethod || 'COD');
    const [razorpayKey, setRazorpayKey] = useState('');
    const [stripePromise, setStripePromise] = useState<any>(null);
    const [clientSecret, setClientSecret] = useState('');
    const [intentError, setIntentError] = useState<string | null>(null);
    const [isMock, setIsMock] = useState(false);

    // Form state
    const [shippingAddress, setShippingAddress] = useState({
        address: '',
        city: '',
        postalCode: '',
        country: 'India'
    });

    useEffect(() => {
        fetchCart();
        initStripe();
    }, []);

    const initStripe = async () => {
        try {
            const { data } = await PaymentService.getConfig();
            if (data.razorpayKey) setRazorpayKey(data.razorpayKey);
            if (data.publishableKey && !data.isMock) {
                setStripePromise(loadStripe(data.publishableKey));
            } else {
                // If it's mock or no key, we don't load Stripe
                setIsMock(true);
            }
        } catch (error) {
            console.error("Stripe config failed", error);
            setIntentError("Failed to load payment configuration.");
        }
    };
    const fetchCart = async () => {
        try {
            const { data } = await CartService.getCart();
            if (!data.cartItems || data.cartItems.length === 0) {
                navigate('/retail');
                toast.info('Your cart is empty!');
                return;
            }
            setCart(data);
        } catch (error) {
            console.error("Error fetching cart:", error);
            navigate('/login');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        if (paymentMethod === 'Stripe' && cart) {
            createIntent();
        }
    }, [paymentMethod, cart]);
    const createIntent = async () => {
        setIntentError(null);
        setIsMock(false);
        try {
            const { data } = await PaymentService.createPaymentIntent(cart.totalPrice * 1.18);
            if (data.isMock) {
                setIsMock(true);
            }
            setClientSecret(data.clientSecret);
        } catch (error: any) {
            console.error("Failed to create intent", error);
            setIntentError(error.response?.data?.message || "Failed to initialize payment.");
        }
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setShippingAddress({ ...shippingAddress, [e.target.name]: e.target.value });
    };

    const handlePlaceOrder = async (stripePaymentId?: string) => {
        if (!shippingAddress.address || !shippingAddress.city || !shippingAddress.postalCode) {
            toast.warning('Please fill in all shipping details');
            return;
        }

        setIsSubmitting(true);
        try {
            const orderData = {
                orderItems: cart.cartItems.map((item: any) => {
                    if (!item || !item.product) return null;
                    const prod = item.product;
                    return {
                        title: prod.title || prod.name || "Untitled Product",
                        quantity: item.quantity,
                        image: prod.thumbnail || (prod.images && prod.images[0]) || prod.image || "https://via.placeholder.com/150",
                        price: Number(prod.price ?? prod.pricePerUnit ?? 0) || 0,
                        product: prod._id
                    };
                }).filter(Boolean),
                shippingAddress,
                paymentMethod: paymentMethod,
                paymentResult: stripePaymentId ? { id: stripePaymentId, status: 'succeeded' } : undefined,
                itemsPrice: cart.totalPrice,
                shippingPrice: 0,
                taxPrice: cart.totalPrice * 0.18,
                totalPrice: cart.totalPrice * 1.18,
                isPaid: !!stripePaymentId,
                paidAt: stripePaymentId ? new Date() : undefined
            };

            const { data } = await OrderService.create(orderData);
            toast.success('Order placed successfully!');
            navigate(`/payment-success?orderId=${data._id}`);
        } catch (error) {
            console.error("Error placing order:", error);
            toast.error('Failed to place order.');
        } finally {
            setIsSubmitting(false);
        }
    };

    if (isLoading) {
        return (
            <Box sx={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <CircularProgress color="inherit" />
            </Box>
        );


    }

    const loadRazorpay = () => {
        return new Promise((resolve) => {
            const script = document.createElement('script');
            script.src = 'https://checkout.razorpay.com/v1/checkout.js';
            script.onload = () => resolve(true);
            script.onerror = () => resolve(false);
            document.body.appendChild(script);
        });
    };

    const handleRazorpayPayment = async () => {
        if (!shippingAddress.address || !shippingAddress.city || !shippingAddress.postalCode) {
            toast.warning('Please fill in all shipping details first');
            return;
        }

        const res = await loadRazorpay();
        if (!res) {
            toast.error('Razorpay SDK failed to load. Are you online?');
            return;
        }

        try {
            const { data: order } = await PaymentService.createRazorpayOrder(cart.totalPrice * 1.18);

            if (order.isMock) {
                toast.info("Payment is in demo mode. Placing order.");
                await handlePlaceOrder('mock_' + order.id);
                return;
            }

            const options = {
                key: razorpayKey || "rzp_test_YourKeyHere",
                amount: order.amount,
                currency: order.currency,
                name: "AtoZ Marketplace",
                description: "Transaction",
                order_id: order.id,
                handler: async function (response: any) {
                    handlePlaceOrder(response.razorpay_payment_id);
                },
                prefill: {
                    name: "User Name",
                    email: "user@example.com",
                    contact: "9999999999"
                },
                theme: {
                    color: "#3399cc"
                }
            };
            const rzp1 = new (window as any).Razorpay(options);
            rzp1.open();
        } catch (error) {
            console.error("Razorpay Error:", error);
            toast.error("Payment initiation failed");
        }
    };

    const appearance = { theme: 'stripe' as const };
    const options = { clientSecret, appearance };

    return (
        <Box sx={{ minHeight: '100vh', bgcolor: '#f8fafc' }}>
            <Navbar />

            <Container maxWidth="lg" sx={{ py: 6 }}>
                <IconButton onClick={() => navigate(-1)} sx={{ mb: 2, bgcolor: 'white', '&:hover': { bgcolor: '#f1f5f9' } }}>
                    <ArrowBackIcon />
                </IconButton>

                <Typography variant="h3" sx={{ fontWeight: 900, mb: 5, color: '#0f172a' }}>
                    Checkout
                </Typography>

                <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, gap: 4 }}>

                    {/* Left: Shipping & Payment */}
                    <Box sx={{ flex: 1 }}>
                        <Paper elevation={0} sx={{ p: 4, borderRadius: 6, border: '1px solid #e2e8f0', mb: 4 }}>
                            <Typography variant="h6" sx={{ fontWeight: 800, mb: 3 }}>Shipping Address</Typography>
                            <Stack spacing={3}>
                                <TextField fullWidth label="Full Address" name="address" value={shippingAddress.address} onChange={handleInputChange} variant="outlined" sx={{ '& .MuiOutlinedInput-root': { borderRadius: 3 } }} />
                                <TextField fullWidth label="City" name="city" value={shippingAddress.city} onChange={handleInputChange} variant="outlined" sx={{ '& .MuiOutlinedInput-root': { borderRadius: 3 } }} />
                                <Box sx={{ display: 'flex', gap: 2 }}>
                                    <TextField fullWidth label="Postal Code" name="postalCode" value={shippingAddress.postalCode} onChange={handleInputChange} variant="outlined" sx={{ '& .MuiOutlinedInput-root': { borderRadius: 3 } }} />
                                    <TextField fullWidth label="Country" name="country" value={shippingAddress.country} disabled variant="outlined" sx={{ '& .MuiOutlinedInput-root': { borderRadius: 3 } }} />
                                </Box>
                            </Stack>
                        </Paper>

                        <Paper elevation={0} sx={{ p: 4, borderRadius: 6, border: '1px solid #e2e8f0' }}>
                            <Typography variant="h6" sx={{ fontWeight: 800, mb: 3 }}>Select Payment Method</Typography>
                            <FormControl component="fieldset" fullWidth>
                                <RadioGroup value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}>
                                    <Paper variant="outlined" sx={{ p: 2, mb: 2, borderRadius: 3, border: paymentMethod === 'COD' ? '2px solid black' : '1px solid #e2e8f0' }}>
                                        <FormControlLabel value="COD" control={<Radio color="default" />} label={
                                            <Box>
                                                <Typography sx={{ fontWeight: 700 }}>Cash on Delivery (COD)</Typography>
                                                <Typography variant="caption" sx={{ color: '#64748b' }}>Pay when your order reaches your doorstep.</Typography>
                                            </Box>
                                        } sx={{ width: '100%', m: 0 }} />
                                    </Paper>

                                    <Paper variant="outlined" sx={{ p: 2, mb: 2, borderRadius: 3, border: paymentMethod === 'Razorpay' ? '2px solid black' : '1px solid #e2e8f0' }}>
                                        <FormControlLabel value="Razorpay" control={<Radio color="default" />} label={
                                            <Box>
                                                <Typography sx={{ fontWeight: 700 }}>Razorpay (UPI / Cards)</Typography>
                                                <Typography variant="caption" sx={{ color: '#64748b' }}>Secure payment via Razorpay.</Typography>
                                            </Box>
                                        } sx={{ width: '100%', m: 0 }} />
                                        {paymentMethod === 'Razorpay' && (
                                            <Button
                                                variant="contained"
                                                fullWidth
                                                onClick={handleRazorpayPayment}
                                                sx={{ mt: 2, bgcolor: '#3399cc', color: 'white', fontWeight: 700 }}
                                            >
                                                Pay with Razorpay
                                            </Button>
                                        )}
                                    </Paper>

                                    <Paper variant="outlined" sx={{ p: 2, borderRadius: 3, border: paymentMethod === 'Stripe' ? '2px solid black' : '1px solid #e2e8f0' }}>
                                        <FormControlLabel value="Stripe" control={<Radio color="default" />} label={
                                            <Box>
                                                <Typography sx={{ fontWeight: 700 }}>Stripe (International)</Typography>
                                                <Typography variant="caption" sx={{ color: '#64748b' }}>Credit/Debit Cards.</Typography>
                                            </Box>
                                        } sx={{ width: '100%', m: 0 }} />

                                        {paymentMethod === 'Stripe' && (
                                            <Box sx={{ mt: 2 }}>
                                                {isMock ? (
                                                    <Box sx={{ p: 2, bgcolor: '#f0fdf4', borderRadius: 2, border: '1px solid #bbf7d0', textAlign: 'center' }}>
                                                        <Typography variant="body2" color="success.main" sx={{ mb: 2, fontWeight: 700 }}>
                                                            Development Mode: Stripe Mock Active
                                                        </Typography>
                                                        <Button
                                                            variant="contained"
                                                            color="success"
                                                            onClick={() => handlePlaceOrder(clientSecret)}
                                                            fullWidth
                                                            sx={{ fontWeight: 800 }}
                                                        >
                                                            Simulate Successful Payment
                                                        </Button>
                                                    </Box>
                                                ) : clientSecret && stripePromise && !isMock ? (
                                                    <Box sx={{ p: 2, bgcolor: '#f8fafc', borderRadius: 2 }}>
                                                        <Elements options={options} stripe={stripePromise}>
                                                            <CheckoutForm amount={cart.totalPrice * 1.18} onSuccess={handlePlaceOrder} />
                                                        </Elements>
                                                    </Box>
                                                ) : (
                                                    <Box sx={{ p: 2, bgcolor: '#fff1f2', borderRadius: 2, border: '1px solid #fecdd3' }}>
                                                        <Typography color="error" variant="body2">
                                                            {intentError || "Loading secure payment..."}
                                                        </Typography>
                                                    </Box>
                                                )}
                                            </Box>
                                        )}
                                    </Paper>
                                </RadioGroup>
                            </FormControl>
                        </Paper>
                    </Box>

                    {/* Right: Order Summary */}
                    <Box sx={{ width: { xs: '100%', md: 400 } }}>
                        <Paper elevation={0} sx={{ p: 4, borderRadius: 6, border: '1px solid #e2e8f0', bgcolor: 'white', position: 'sticky', top: 120 }}>
                            <Typography variant="h6" sx={{ fontWeight: 800, mb: 3 }}>Order Summary</Typography>
                            <Stack spacing={2} sx={{ mb: 3 }}>
                                {cart.cartItems.map((item: any) => {
                                    if (!item || !item.product) return null;
                                    const price = Number(item.product?.price ?? item.product?.pricePerUnit ?? 0) || 0;
                                    const qty = Number(item.quantity) || 0;
                                    const lineTotal = price * qty;
                                    return (
                                        <Box key={item.product._id} sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                            <Typography variant="body2" sx={{ fontWeight: 600 }}>{item.product.title} x {qty}</Typography>
                                            <Typography variant="body2" sx={{ fontWeight: 700 }}>Ôé╣{lineTotal.toLocaleString()}</Typography>
                                        </Box>
                                    );
                                })}
                            </Stack>
                            <Divider sx={{ my: 3 }} />
                            <Stack spacing={2}>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <Typography variant="body2" color="textSecondary">Subtotal</Typography>
                                    <Typography variant="body2" sx={{ fontWeight: 700 }}>Ôé╣{(Number(cart.totalPrice) || 0).toLocaleString()}</Typography>
                                </Box>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <Typography variant="body2" color="textSecondary">GST (18%)</Typography>
                                    <Typography variant="body2" sx={{ fontWeight: 700 }}>Ôé╣{((Number(cart.totalPrice) || 0) * 0.18).toLocaleString()}</Typography>
                                </Box>
                                <Divider />
                                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <Typography variant="h6" sx={{ fontWeight: 900 }}>Total</Typography>
                                    <Typography variant="h6" sx={{ fontWeight: 900 }}>Ôé╣{((Number(cart.totalPrice) || 0) * 1.18).toLocaleString()}</Typography>
                                </Box>
                            </Stack>

                            {paymentMethod === 'COD' && (
                                <Button
                                    fullWidth variant="contained" size="large"
                                    disabled={isSubmitting}
                                    onClick={() => handlePlaceOrder()}
                                    sx={{ bgcolor: '#B4D5DC', color: 'black', borderRadius: 4, py: 2, mt: 4, fontWeight: 800, '&:hover': { bgcolor: '#9cc3cd' } }}
                                >
                                    {isSubmitting ? 'Processing...' : 'Place Order (COD)'}
                                </Button>
                            )}
                        </Paper>
                    </Box>
                </Box>
            </Container>
            <Footer />
        </Box>
    );
};

export default Checkout;

import { Box, Container, Dialog, DialogActions, DialogContent, DialogTitle, TextField, Button, Stack, Typography } from '@mui/material';
import Navbar from '../WrapperComponents/Navbar';
import Footer from '../WrapperComponents/Footer';
import FreelancersFeed from '../SpecifiedComponents/Freelancers/Components/FreelancersFeed';
import FreelancerSidebar from '../SpecifiedComponents/Freelancers/Components/FreelancerSidebar';
import FreelancerSidebarBuyer from '../SpecifiedComponents/Freelancers/Components/FreelancerSidebarBuyer';
import FreelanceBanner from '../SpecifiedComponents/Freelancers/Components/FreelanceBanner';
import { useState, useEffect } from 'react';
import { FreelanceService, AuthService } from '../../services/api';

// Define interface locally to avoid 'export not found' issues
interface Post {
    id: number | string;
    title: string;
    description: string;
    price: number;
    image: string;
    status: string;
    tagColor: string;
    tagTextColor: string;
    views: string;
    time: string;
    date?: string;
    currency: string;
    unit?: string;
    nameDisplay?: string;
    category?: string;
}

const Freelance = () => {
    const userRole = localStorage.getItem('userRole');
    const isBuyer = userRole === 'Buyer';
    const isSeller = userRole === 'Seller';
    const [posts, setPosts] = useState<Post[]>([]);
    const [isFreelancerRegistered, setIsFreelancerRegistered] = useState(false);

    const [interestDialog, setInterestDialog] = useState(false);
    const [selectedPostId, setSelectedPostId] = useState<string | null>(null);
    const [interestForm, setInterestForm] = useState({ details: '', price: '', days: '' });
    const [submittingInterest, setSubmittingInterest] = useState(false);

    const fetchPosts = async () => {
        try {
            const { data } = await FreelanceService.getAll();
            const formattedPosts = data.map((p: any) => ({
                id: p._id,
                title: p.title || "No Title",
                description: p.description || "No Description",
                price: p.price || 0,
                currency: p.currency || "$",
                status: p.status || "NEW",
                tagColor: p.tagColor || (p.status === 'APPROVED' ? "#bef264" : "#e2e8f0"),
                tagTextColor: p.tagTextColor || (p.status === 'APPROVED' ? "#1a2e05" : "#475569"),
                views: p.views || "0 views",
                time: p.time || new Date(p.createdAt).toLocaleDateString(),
                date: new Date(p.createdAt).toLocaleDateString(),
                nameDisplay: p.nameDisplay || p.user?.profile?.name || p.user?.username || "Anonymous",
                category: p.category || "General",
                unit: p.unit || "/hr",
                contact: p.contact,
                email: p.email,
                location: p.location,
                image: p.image || "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80"
            }));
            setPosts(formattedPosts);
        } catch (error) {
            console.error("Failed to fetch posts", error);
        }
    };

    const fetchUserStatus = async () => {
        try {
            const token = localStorage.getItem('token');
            if (token) {
                const { data: me } = await AuthService.getMe();
                setIsFreelancerRegistered(me?.freelancer?.isRegistered || false);
            }
        } catch (error) {
            console.error("Failed to fetch user status", error);
        }
    };

    useEffect(() => {
        fetchPosts();
        fetchUserStatus();
    }, []);

    const handleInterestClick = async (postId: string | number) => {
        const token = localStorage.getItem('token');
        if (!token) {
            alert("Please login first to show interest");
            return;
        }

        if (!isSeller) {
            alert("Only Seller accounts can submit interest requests.");
            return;
        }

        if (!isFreelancerRegistered) {
            alert("Registration is compulsory! Please register as a freelancer using the sidebar to show interest in this post.");
            return;
        }

        setSelectedPostId(postId.toString());
        setInterestDialog(true);
    };

    const submitInterestForm = async () => {
        if (!selectedPostId) return;

        try {
            setSubmittingInterest(true);
            await FreelanceService.submitInterest(selectedPostId, {
                details: interestForm.details,
                proposedPrice: Number(interestForm.price),
                estimatedDuration: interestForm.days
            });
            alert("Success! Your interest has been recorded. The admin will review your request shortly.");
            setInterestDialog(false);
            setInterestForm({ details: '', price: '', days: '' });
        } catch (error: any) {
            alert(error.response?.data?.message || "Failed to submit interest");
        } finally {
            setSubmittingInterest(false);
        }
    };

    const handlePost = async (newPost: any) => {
        try {
            const { id, ...postData } = newPost;
            await FreelanceService.create(postData);
            fetchPosts();
        } catch (error) {
            console.error("Failed to create post", error);
        }
    };

    return (
        <Box sx={{ minHeight: '100vh', bgcolor: '#f1f5f9' }}>
            <Navbar />
            <Container maxWidth="xl" sx={{ mt: 4, mb: 8 }}>
                <FreelanceBanner />
                <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, gap: 4, alignItems: 'flex-start' }}>
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                        <FreelancersFeed
                            posts={posts}
                            onInterestClick={handleInterestClick}
                            showInterestButton={!isBuyer && isSeller}
                        />
                    </Box>
                    <Box sx={{ width: { xs: '100%', md: 340, lg: 380 }, flexShrink: 0, position: { md: 'sticky' }, top: 20 }}>
                        {isBuyer ? (
                            <FreelancerSidebarBuyer onPost={handlePost} />
                        ) : (
                            <FreelancerSidebar />
                        )}
                    </Box>
                </Box>
            </Container>

            {/* Interest Dialog (Seller -> backend: /posts/:id/interest) */}
            <Dialog open={interestDialog} onClose={() => setInterestDialog(false)} maxWidth="sm" fullWidth>
                <DialogTitle sx={{ fontWeight: 900 }}>Submit Interest</DialogTitle>
                <DialogContent>
                    <Typography variant="body2" sx={{ color: '#64748b', mb: 2 }}>
                        Fill the details, your proposed price, and delivery days. This request will appear in the Admin panel under <b>Interest Requests</b>.
                    </Typography>
                    <Stack spacing={2.5} sx={{ pt: 1 }}>
                        <TextField
                            label="Details"
                            multiline
                            rows={3}
                            value={interestForm.details}
                            onChange={(e) => setInterestForm({ ...interestForm, details: e.target.value })}
                            placeholder="Explain your plan / what you will deliver"
                            fullWidth
                        />
                        <TextField
                            label="Price (Ôé╣)"
                            type="number"
                            value={interestForm.price}
                            onChange={(e) => setInterestForm({ ...interestForm, price: e.target.value })}
                            fullWidth
                        />
                        <TextField
                            label="Delivery days"
                            value={interestForm.days}
                            onChange={(e) => setInterestForm({ ...interestForm, days: e.target.value })}
                            placeholder="e.g. 5"
                            fullWidth
                        />
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3 }}>
                    <Button onClick={() => setInterestDialog(false)} sx={{ fontWeight: 800, color: '#64748b' }}>
                        Cancel
                    </Button>
                    <Button
                        onClick={submitInterestForm}
                        disabled={submittingInterest}
                        variant="contained"
                        sx={{ bgcolor: 'black', color: 'white', fontWeight: 900, '&:hover': { bgcolor: '#111' } }}
                    >
                        {submittingInterest ? 'Submitting...' : 'Submit'}
                    </Button>
                </DialogActions>
            </Dialog>

            <Footer />
        </Box>
    );
};

export default Freelance;

