                                        size="small"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                        }}
                                    >
                                        <FavoriteBorderIcon fontSize="small" />
                                    </IconButton>
                                    <Box
                                        sx={{
                                            position: 'absolute',
                                            top: 10,
                                            left: 10,
                                            bgcolor: '#ff6b6b',
