                    ))}
                </Grid>

                {displayProducts.length === 0 && (
                    <Box sx={{ textAlign: 'center', py: 8 }}>
                        <Typography variant="h5" sx={{ color: 'text.secondary' }}>
                            No products found
                        </Typography>
                    </Box>
                )}
            </Container>

            <Footer />
        </Box>
    );
};

export default OneDayOffer;

import { useEffect, useState } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { Box, Container, Typography, Paper, Button, Divider, List, ListItem, ListItemText, CircularProgress, Avatar, Chip, Stack } from '@mui/material';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import Navbar from '../WrapperComponents/Navbar';
import Footer from '../WrapperComponents/Footer';
import { OrderService } from '../../services/api';

const PaymentSuccess = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const [order, setOrder] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    const orderId = new URLSearchParams(location.search).get('orderId');

    useEffect(() => {
        if (!orderId) {
            navigate('/');
            return;
        }

        const fetchOrder = async () => {
            try {
                const { data } = await OrderService.getOrderById(orderId);
                setOrder(data);
            } catch (error) {
                console.error("Failed to fetch order", error);
            } finally {
                setLoading(false);
            }
        };

        fetchOrder();
    }, [orderId, navigate]);

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', background: 'linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%)' }}>
                <CircularProgress sx={{ color: '#B4D5DC' }} />
            </Box>
        );
    }

    return (
        <Box sx={{ bgcolor: '#f8fafc', minHeight: '100vh', pb: 10 }}>
            <Navbar />
            <Container maxWidth="md" sx={{ py: 8 }}>
                <Paper
                    elevation={0}
                    sx={{
                        p: { xs: 4, md: 8 },
                        borderRadius: 8,
                        textAlign: 'center',
                        border: '1px solid #e2e8f0',
                        position: 'relative',
                        overflow: 'hidden',
                        bgcolor: 'rgba(255, 255, 255, 0.8)',
                        backdropFilter: 'blur(20px)',
                        boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.05)'
                    }}
                >
                    <Box sx={{
                        position: 'absolute', top: 0, left: 0, right: 0, height: 8,
                        background: 'linear-gradient(90deg, #B4D5DC 0%, #9cc3cd 100%)'
                    }} />

                    <CheckCircleOutlineIcon sx={{ fontSize: 100, color: '#B4D5DC', mb: 3 }} />
                    <Typography variant="h3" sx={{ fontWeight: 900, mb: 1, letterSpacing: -1 }}>
                        Order Confirmed!
                    </Typography>
                    <Typography variant="h6" sx={{ color: '#64748b', mb: 5, fontWeight: 500 }}>
                        Your payment was successful and your order is on its way.
                    </Typography>

                    <Box sx={{ textAlign: 'left', bgcolor: '#f8fafc', p: 4, borderRadius: 6, border: '1px solid #f1f5f9' }}>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4 }}>
                            <Box>
                                <Typography variant="overline" sx={{ color: '#94a3b8', fontWeight: 800 }}>Order Number</Typography>
                                <Typography variant="h6" sx={{ fontWeight: 800 }}>#{order?._id.slice(-8).toUpperCase()}</Typography>
                            </Box>
                            <Chip label="Processing" sx={{ bgcolor: '#fef3c7', color: '#b45309', fontWeight: 800 }} />
                        </Box>

                        <Divider sx={{ mb: 4, borderStyle: 'dashed' }} />

                        <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 2 }}>Order Details</Typography>
                        <List disablePadding>
                            {order?.orderItems?.map((item: any) => {
                                if (!item) return null;
                                return (
                                    <ListItem key={item._id} sx={{ px: 0, py: 2 }}>
                                        <Avatar src={item.image} variant="rounded" sx={{ width: 50, height: 50, mr: 2, borderRadius: 2 }} />
                                        <ListItemText
                                            primary={item.title || item.name}
                                            primaryTypographyProps={{ fontWeight: 700 }}
                                            secondary={`Quantity: ${item.quantity}`}
                                        />
                                        <Typography sx={{ fontWeight: 800 }}>
                                            Ôé╣{((Number(item.price) || 0) * (Number(item.quantity) || 0)).toLocaleString('en-IN')}
                                        </Typography>
                                    </ListItem>
                                );
                            })}
                        </List>

                        <Stack spacing={2} sx={{ mt: 4, p: 3, bgcolor: 'white', borderRadius: 4, border: '1px solid #e2e8f0' }}>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                <Typography sx={{ color: '#64748b' }}>Subtotal</Typography>
                                <Typography sx={{ fontWeight: 600 }}>Ôé╣{(Number(order?.itemsPrice) || 0).toLocaleString('en-IN')}</Typography>
                            </Box>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                <Typography sx={{ color: '#64748b' }}>Shipping</Typography>
                                <Typography sx={{ fontWeight: 600 }}>Ôé╣{(Number(order?.shippingPrice) || 0).toLocaleString('en-IN')}</Typography>
                            </Box>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                <Typography sx={{ color: '#64748b' }}>Tax (GST)</Typography>
                                <Typography sx={{ fontWeight: 600 }}>Ôé╣{(Number(order?.taxPrice) || 0).toLocaleString('en-IN')}</Typography>
                            </Box>
                            <Divider />
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                <Typography sx={{ fontWeight: 800, fontSize: '1.2rem' }}>Total Amount</Typography>
                                <Typography sx={{ fontWeight: 900, fontSize: '1.2rem', color: '#000' }}>Ôé╣{(Number(order?.totalPrice) || 0).toLocaleString('en-IN')}</Typography>
                            </Box>
                        </Stack>

                        <Box sx={{ mt: 4, display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' }, gap: 4 }}>
                            <Box>
                                <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 1 }}>Delivering to</Typography>
                                <Typography variant="body2" sx={{ color: '#475569', lineHeight: 1.6 }}>
                                    {order?.shippingAddress.address}<br />
                                    {order?.shippingAddress.city}, {order?.shippingAddress.postalCode}<br />
                                    {order?.shippingAddress.country}
                                </Typography>
                            </Box>

                            <Box>
                                <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 1 }}>Payment Method</Typography>
                                <Stack direction="row" alignItems="center" spacing={1.5} sx={{ p: 2, border: '1px solid #e2e8f0', borderRadius: 3, display: 'inline-flex', bgcolor: 'white' }}>
                                    <CreditCardIcon sx={{ color: '#000' }} />
                                    <Box>
                                        <Typography variant="body2" sx={{ fontWeight: 800, lineHeight: 1.2 }}>
                                            {order?.paymentMethod || 'Credit Card'}
                                        </Typography>
                                        <Typography variant="caption" sx={{ color: '#64748b', display: 'block' }}>
                                            Ending in ÔÇóÔÇóÔÇóÔÇó 4242
                                        </Typography>
                                    </Box>
                                    <Chip label="PAID" size="small" color="success" sx={{ height: 24, fontSize: '0.7rem', fontWeight: 800, borderRadius: 1 }} />
                                </Stack>
                            </Box>
                        </Box>
                    </Box>

                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} justifyContent="center" sx={{ mt: 8 }}>
                        <Button
                            component={Link}
                            to="/profile"
                            variant="contained"
                            fullWidth
                            sx={{
                                bgcolor: '#000',
                                color: 'white',
                                py: 2,
                                px: 4,
                                borderRadius: 4,
                                fontWeight: 800,
                                fontSize: '1rem',
                                textTransform: 'none',
                                '&:hover': { bgcolor: '#1e293b' }
                            }}
                        >
                            Track Your Order
                        </Button>
                        <Button
                            component={Link}
                            to="/"
                            variant="outlined"
                            fullWidth
                            sx={{
                                borderColor: '#e2e8f0',
                                color: '#000',
                                py: 2,
                                px: 4,
                                borderRadius: 4,
                                fontWeight: 800,
                                fontSize: '1rem',
                                textTransform: 'none',
                                '&:hover': { borderColor: '#000', bgcolor: 'transparent' }
                            }}
                        >
                            Continue Shopping
                        </Button>
                    </Stack>
                </Paper>
            </Container>
            <Footer />
        </Box>
    );
};

export default PaymentSuccess;

import { useState, useEffect } from 'react';
import {
    Box, Typography, Button, Avatar, Paper, Chip, IconButton,
    Stack, Container, Grid, Dialog, DialogTitle, DialogContent, DialogActions, TextField
} from '@mui/material';
import { useNavigate, useSearchParams } from 'react-router-dom';

// Icons
import LogoutIcon from '@mui/icons-material/Logout';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ShoppingCartOutlinedIcon from '@mui/icons-material/ShoppingCartOutlined';
import FavoriteBorderOutlinedIcon from '@mui/icons-material/FavoriteBorderOutlined';
import DarkModeIcon from '@mui/icons-material/DarkMode';
import NotificationsNoneOutlinedIcon from '@mui/icons-material/NotificationsNoneOutlined';
import GridViewIcon from '@mui/icons-material/GridView';
import LocalMallOutlinedIcon from '@mui/icons-material/LocalMallOutlined';
import AccountBalanceWalletOutlinedIcon from '@mui/icons-material/AccountBalanceWalletOutlined';
import SettingsOutlinedIcon from '@mui/icons-material/SettingsOutlined';
import DiamondIcon from '@mui/icons-material/Diamond';
import KeyboardArrowLeftIcon from '@mui/icons-material/KeyboardArrowLeft';
import KeyboardArrowRightIcon from '@mui/icons-material/KeyboardArrowRight';

import { CartService, WishlistService, OrderService, AuthService, UserService, WholesaleService, ResaleService, QProductService, FreelanceService } from '../../services/api';
import { toast } from 'react-toastify';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import StoreIcon from '@mui/icons-material/Store';
import WarehouseIcon from '@mui/icons-material/Warehouse';
import FlashOnIcon from '@mui/icons-material/FlashOn';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import WorkOutlineIcon from '@mui/icons-material/WorkOutline';
import EmailOutlinedIcon from '@mui/icons-material/EmailOutlined';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import ImageOutlinedIcon from '@mui/icons-material/ImageOutlined';

const Profile = () => {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const [userData, setUserData] = useState<any>({
        name: 'Dinesh Kumar M',
        email: 'dinesh.kumar@example.com',
        phone: '+919876543210',
        role: 'Verified Member',
        lastLogin: '2 hours ago',
        avatar: '',
        uniqueId: ''
    });

    const [cartCount, setCartCount] = useState(0);
    const [wishlistCount, setWishlistCount] = useState(0);
    const [cartItems, setCartItems] = useState<any[]>([]);
    const [wishlistItems, setWishlistItems] = useState<any[]>([]);
    const [orders, setOrders] = useState<any[]>([]);
    const [currentView, setCurrentView] = useState<'overview' | 'cart' | 'wishlist' | 'wallet'>('overview');
    type ChannelKey = 'retail' | 'wholesale' | 'quick' | 'resale' | 'freelance' | null;
    const [selectedChannel, setSelectedChannel] = useState<ChannelKey>(null);
    const [wholesaleProducts, setWholesaleProducts] = useState<any[]>([]);
    const [resaleItems, setResaleItems] = useState<any[]>([]);
    const [qCommerceProducts, setQCommerceProducts] = useState<any[]>([]);
    const [freelancePosts, setFreelancePosts] = useState<any[]>([]);
    const [channelLoading, setChannelLoading] = useState(false);

    // Edit Profile State (all editable except ID)
    const [isEditOpen, setIsEditOpen] = useState(false);
    const [editName, setEditName] = useState('');
    const [editEmail, setEditEmail] = useState('');
    const [editPhone, setEditPhone] = useState('');
    const [editAvatar, setEditAvatar] = useState('');
    const [savingProfile, setSavingProfile] = useState(false);

    const handleOpenEdit = () => {
        setEditName(userData.name);
        setEditEmail(userData.email || '');
        setEditPhone(userData.phone || '');
        setEditAvatar(userData.avatar || '');
        setIsEditOpen(true);
    };

    const handleEditSave = async () => {
        setSavingProfile(true);
        try {
            const updated = {
                name: editName,
                email: editEmail,
                phone: editPhone,
                avatar: editAvatar
            };
            setUserData((prev: any) => ({ ...prev, ...updated }));
            localStorage.setItem('userName', editName);
            localStorage.setItem('userProfileImage', editAvatar);
            if (userData.uniqueId) {
                await UserService.updateUserProfile(userData.uniqueId, {
                    username: editName,
                    email: editEmail,
                    profile: { ...userData.profile, avatar: editAvatar, phone: editPhone }
                }).catch(() => { });
            }
        } finally {
            setSavingProfile(false);
            setIsEditOpen(false);
        }
    };

    useEffect(() => {
        const view = searchParams.get('view');
        if (view === 'cart' || view === 'wishlist' || view === 'wallet' || view === 'overview') {
            setCurrentView(view as any);
        }
    }, [searchParams]);

    useEffect(() => {
        const savedName = localStorage.getItem('userName');
        const savedAvatar = localStorage.getItem('userProfileImage');
        if (savedName) setUserData((prev: any) => ({ ...prev, name: savedName }));
        if (savedAvatar) setUserData((prev: any) => ({ ...prev, avatar: savedAvatar }));

        fetchData();
    }, []);

    useEffect(() => {
        if (!selectedChannel) return;
        setChannelLoading(true);
        const load = async () => {
            try {
                if (selectedChannel === 'wholesale') {
                    const { data } = await WholesaleService.getMyProducts().catch(() => ({ data: [] }));
                    setWholesaleProducts(Array.isArray(data) ? data : []);
                } else if (selectedChannel === 'resale') {
                    const { data } = await ResaleService.getMyProducts().catch(() => ({ data: [] }));
                    setResaleItems(Array.isArray(data) ? data : []);
                } else if (selectedChannel === 'quick') {
                    const { data } = await QProductService.getAll().catch(() => ({ data: [] }));
                    setQCommerceProducts(Array.isArray(data) ? data : []);
                } else if (selectedChannel === 'freelance') {
                    const { data } = await FreelanceService.getAll().catch(() => ({ data: [] }));
                    setFreelancePosts(Array.isArray(data) ? data : []);
                }
            } finally {
                setChannelLoading(false);
            }
        };
        load();
    }, [selectedChannel]);

    const fetchData = async () => {
        try {
            const [cartRes, wishlistRes, ordersRes, userRes] = await Promise.all([
                CartService.getCart().catch(() => ({ data: { cartItems: [] } })),
                WishlistService.getWishlist().catch(() => ({ data: { products: [] } })),
                OrderService.getMyOrders().catch(() => ({ data: [] })),
                AuthService.getMe().catch(() => ({ data: null }))
            ]);

            if (userRes && userRes.data) {
                const d = userRes.data;
                setUserData((prev: any) => ({
                    ...prev,
                    name: d.username || d.profile?.name || prev.name,
                    email: d.email || d.profile?.email || prev.email,
                    phone: d.phone || d.profile?.phone || prev.phone,
                    role: d.role || prev.role,
                    uniqueId: d.uniqueId || d._id,
                    avatar: d.profile?.avatar || prev.avatar,
                    profile: d.profile || prev.profile
                }));
            }

            setCartCount(cartRes.data?.cartItems?.length || 0);
            setCartItems(cartRes.data?.cartItems || []);
            setWishlistCount(wishlistRes.data?.products?.length || 0);
            setWishlistItems(wishlistRes.data?.products || []);

            if (ordersRes.data && ordersRes.data.length > 0) {
                // specific logic to sort by date if backend doesn't sorting
                const sortedOrders = ordersRes.data.sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
                setOrders(sortedOrders);
            }
        } catch (error) {
            console.error("Profile data fetch error:", error);
        }
    };

    const handleRemoveWishlist = async (productId: string) => {
        try {
            await WishlistService.removeFromWishlist(productId);
            setWishlistItems(prev => prev.filter(item => item._id !== productId));
            setWishlistCount(prev => prev - 1);
            toast.success("Removed from wishlist");
        } catch (error) {
            console.error("Error removing from wishlist:", error);
            toast.error("Failed to remove");
        }
    };

    const handleAddToCart = async (product: any) => {
        try {
            // Map frontend types to backend CartService expectations
            const typeMapping: any = {
                'retail': 'Retail',
                'wholesale': 'Wholesale',
                'q-commerce': 'Quick',
                'resale': 'Resale'
            };
            const mappedType = typeMapping[product.type] || 'Retail';

            await CartService.addToCart({
                productId: product._id,
                quantity: 1,
                type: mappedType
            });
            setCartCount(prev => prev + 1);
            toast.success("Added to cart!");
        } catch (error) {
            console.error("Error adding to cart:", error);
            toast.error("Failed to add to cart");
        }
    };

    const handleLogout = () => {
        localStorage.clear();
        navigate('/login');
    };

    const getStatusIndex = (status: string) => {
        switch (status) {
            case 'Ordered': return 0;
            case 'Shipped': return 1;
            case 'Out for Delivery': return 2;
            case 'Delivered': return 3;
            default: return 0;
        }
    };

    return (
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: '#fdfdfd' }}>
            {/* Dual Column Sidebar - Hidden on mobile */}
            <Box sx={{ display: { xs: 'none', md: 'flex' }, position: 'fixed', height: '100vh', zIndex: 1300 }}>
                {/* Left Mini Sidebar - Icons */}
                <Box
                    sx={{
                        width: 70,
                        bgcolor: '#000000',
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        py: 4,
                        borderRight: '1px solid rgba(255,255,255,0.05)'
                    }}
                >
                    <Box
                        onClick={() => navigate('/')}
                        sx={{
                            width: 44,
                            height: 44,
                            bgcolor: '#B4D5DC',
                            borderRadius: '50%',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            mb: 6,
                            cursor: 'pointer',
                            transition: 'all 0.3s ease',
                            '&:hover': { transform: 'scale(1.05)', boxShadow: '0 0 15px rgba(180, 213, 220, 0.4)' }
                        }}
                    >
                        <DiamondIcon sx={{ color: 'black', fontSize: 24 }} />
                    </Box>

                    <Stack spacing={3} sx={{ flex: 1 }}>
                        {[
                            { icon: <GridViewIcon />, view: 'overview' },
                            { icon: <ShoppingCartOutlinedIcon />, view: 'cart' },
                            { icon: <FavoriteBorderOutlinedIcon />, view: 'wishlist' },
                            { icon: <AccountBalanceWalletOutlinedIcon />, view: 'wallet' },
                            { icon: <DiamondIcon />, view: 'vouchers' }
                        ].map((item, idx) => (
                            <IconButton
                                key={idx}
                                onClick={() => { setCurrentView(item.view as any); setSelectedChannel(null); }}
                                sx={{
                                    color: currentView === item.view && !selectedChannel ? 'white' : 'rgba(255,255,255,0.3)',
                                    bgcolor: currentView === item.view && !selectedChannel ? 'rgba(255,255,255,0.1)' : 'transparent',
                                    borderRadius: 3,
                                    p: 1.5,
                                    '&:hover': { color: 'white', bgcolor: 'rgba(255,255,255,0.05)' }
                                }}
                            >
                                {item.icon}
                            </IconButton>
                        ))}
                    </Stack>

                    <IconButton sx={{ color: 'rgba(255,255,255,0.3)', mb: 2, '&:hover': { color: 'white' } }}>
                        <SettingsOutlinedIcon />
                    </IconButton>
                </Box>

                {/* Second Column Sidebar - Channels */}
                <Box
                    sx={{
                        width: { md: 200, lg: 220 },
                        bgcolor: '#0d0d0d',
                        display: 'flex',
                        flexDirection: 'column',
                        py: 4,
                        px: 2
                    }}
                >
                    <Typography
                        variant="caption"
                        sx={{
                            color: 'rgba(255,255,255,0.4)',
                            fontWeight: 900,
                            letterSpacing: 1.5,
                            mb: 4,
                            px: 1
                        }}
                    >
                        MARKETPLACE CHANNELS
                    </Typography>

                    <Stack spacing={0.5}>
                        {[
                            { name: 'Retail', icon: <StoreIcon sx={{ fontSize: 20 }} />, channel: 'retail' as ChannelKey },
                            { name: 'Wholesale', icon: <WarehouseIcon sx={{ fontSize: 20 }} />, channel: 'wholesale' as ChannelKey },
                            { name: 'Q-Commerce', icon: <FlashOnIcon sx={{ fontSize: 20 }} />, channel: 'quick' as ChannelKey },
                            { name: 'Resale', icon: <AutorenewIcon sx={{ fontSize: 20 }} />, channel: 'resale' as ChannelKey },
                            { name: 'Freelance', icon: <WorkOutlineIcon sx={{ fontSize: 20 }} />, channel: 'freelance' as ChannelKey }
                        ].map((item) => (
                            <Button
                                key={item.channel}
                                fullWidth
                                startIcon={item.icon}
                                onClick={() => { setSelectedChannel(item.channel); setCurrentView('overview'); }}
                                sx={{
                                    justifyContent: 'flex-start',
                                    color: selectedChannel === item.channel ? 'white' : 'rgba(255,255,255,0.4)',
                                    textTransform: 'none',
                                    fontWeight: 700,
                                    borderRadius: 3,
                                    py: 1.5,
                                    px: 2,
                                    bgcolor: selectedChannel === item.channel ? 'rgba(255,255,255,0.08)' : 'transparent',
                                    '&:hover': { bgcolor: 'rgba(255,255,255,0.05)' }
                                }}
                            >
                                <Typography variant="body2">{item.name}</Typography>
                            </Button>
                        ))}
                    </Stack>

                    <Box sx={{ mt: 'auto', pt: 2, borderTop: '1px solid rgba(255,255,255,0.05)' }}>
                        <Button
                            onClick={handleLogout}
                            startIcon={<LogoutIcon sx={{ fontSize: 18 }} />}
                            sx={{ color: '#ef4444', textTransform: 'none', fontWeight: 700, px: 2 }}
                        >
                            Sign Out
                        </Button>
                    </Box>
                </Box>
            </Box>

            {/* Main Content Area */}
            <Box sx={{ flex: 1, ml: { xs: 0, md: '270px', lg: '290px' }, display: 'flex', flexDirection: 'column' }}>
                <Container maxWidth="xl" sx={{ py: { xs: 3, md: 6 } }}>
                    {/* Header Banner */}
                    <Box
                        sx={{
                            p: { xs: 4, md: 5 },
                            borderRadius: { xs: 6, md: 10 },
                            background: 'linear-gradient(135deg, #e0f2f1 0%, #ffffff 100%)',
                            mb: { xs: 4, md: 6 },
                            position: 'relative',
                            overflow: 'hidden',
                            display: 'flex',
                            flexDirection: { xs: 'column', md: 'row' },
                            alignItems: 'center',
                            textAlign: { xs: 'center', md: 'left' },
                            gap: 4,
                            boxShadow: '0 10px 30px rgba(0,0,0,0.03)',
                            border: '1px solid rgba(255,255,255,0.8)'
                        }}
                    >
                        <Box sx={{ position: 'relative' }}>
                            <Avatar
                                src={userData.avatar}
                                sx={{
                                    width: { xs: 120, md: 160 },
                                    height: { xs: 120, md: 160 },
                                    border: '6px solid white',
                                    boxShadow: '0 20px 40px rgba(0,0,0,0.08)',
                                    bgcolor: '#f1f5f9'
                                }}
                            />
                            <Chip
                                label="ELITE"
                                size="small"
                                sx={{
                                    position: 'absolute',
                                    bottom: 12,
                                    right: 12,
                                    bgcolor: 'black',
                                    color: 'white',
                                    fontWeight: 900,
                                    fontSize: '0.65rem',
                                    height: 20
                                }}
                            />
                        </Box>

                        <Box sx={{ flex: 1 }}>
                            <Stack direction="row" spacing={1.5} alignItems="center" justifyContent={{ xs: 'center', md: 'flex-start' }} sx={{ mb: 1 }}>
                                <Typography variant="h2" sx={{ fontWeight: 900, color: '#0f172a', letterSpacing: -1, fontSize: { xs: '2rem', md: '3rem' } }}>
                                    {userData.name}
                                </Typography>
                                <CheckCircleIcon sx={{ color: '#B4D5DC', fontSize: 26 }} />
                            </Stack>

                            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ mt: 2 }} alignItems={{ xs: 'center', md: 'flex-start' }}>
                                {userData.email && (
                                    <Box sx={{ bgcolor: 'rgba(180, 213, 220, 0.15)', px: 2, py: 1, borderRadius: 5, display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <EmailOutlinedIcon sx={{ fontSize: 16, color: '#64748b' }} />
                                        <Typography variant="body2" sx={{ color: '#64748b', fontWeight: 600 }}>{userData.email}</Typography>
                                    </Box>
                                )}
                                {userData.phone && (
                                    <Box sx={{ bgcolor: 'rgba(180, 213, 220, 0.15)', px: 2, py: 1, borderRadius: 5, display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <PhoneOutlinedIcon sx={{ fontSize: 16, color: '#64748b' }} />
                                        <Typography variant="body2" sx={{ color: '#64748b', fontWeight: 600 }}>{userData.phone}</Typography>
                                    </Box>
                                )}
                            </Stack>

                            <Stack direction="row" spacing={1} alignItems="center" sx={{ mt: 2 }} justifyContent={{ xs: 'center', md: 'flex-start' }}>
                                <Typography variant="caption" sx={{ fontWeight: 800, color: '#94a3b8', letterSpacing: 1 }}>
                                    ÔùÅ ELITE STATUS VERIFIED
                                </Typography>
                            </Stack>
                        </Box>

                        <Box>
                            <Button
                                onClick={handleOpenEdit}
                                variant="contained"
                                sx={{
                                    bgcolor: 'black',
                                    color: 'white',
                                    fontWeight: 900,
                                    borderRadius: 3.5,
                                    px: 4,
                                    py: 1.5,
                                    textTransform: 'none',
                                    boxShadow: '0 4px 15px rgba(0,0,0,0.1)',
                                    '&:hover': { bgcolor: '#1e293b', boxShadow: '0 6px 20px rgba(0,0,0,0.15)' }
                                }}
                            >
                                EDIT PROFILE
                            </Button>
                        </Box>
                    </Box>

                    {/* Dynamic View Replacement */}
                    {currentView === 'overview' && (
                        <>
