import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { Box, Container, Snackbar, Alert, Button } from '@mui/material';
import Navbar from '../WrapperComponents/Navbar';
import Footer from '../WrapperComponents/Footer';

import WholesaleFeed from '../SpecifiedComponents/WholeSale/Components/WholesaleFeed';
import WholesaleUploadForm from '../SpecifiedComponents/WholeSale/Components/WholesaleUploadForm';
import BuyerRequestModal from '../SpecifiedComponents/WholeSale/Components/BuyerRequestModal';
import BuyerRequestsFeed from '../SpecifiedComponents/WholeSale/Components/BuyerRequestsFeed';
import WholesaleHeader from '../SpecifiedComponents/WholeSale/Components/WholesaleHeader';
import CloseIcon from '@mui/icons-material/Close';

const Wholesale = () => {
    const location = useLocation();
    const [view, setView] = useState<'feed' | 'upload' | 'requests'>('feed');
    const [snackbarOpen, setSnackbarOpen] = useState(false);
    const [refreshToken, setRefreshToken] = useState(0);
    const [openRequestDialog, setOpenRequestDialog] = useState(false);

    const handleProductPosted = () => {
        setView('feed');
        setRefreshToken(prev => prev + 1);
        setSnackbarOpen(true);
    };

    const handleRequestSubmit = (request: any) => {
        const existingRequests = JSON.parse(localStorage.getItem('wholesale_requests') || '[]');
        localStorage.setItem('wholesale_requests', JSON.stringify([...existingRequests, request]));
        setRefreshToken(prev => prev + 1);
        setSnackbarOpen(true);
        // If needed, switch to requests view or just notify
        if (localStorage.getItem('userRole') === 'Seller') {
            setView('requests');
        }
    };

    const handleCancelUpload = () => {
        setView('feed');
    };

    useEffect(() => {
        if (location.state && (location.state as any).view) {
            setView((location.state as any).view);
        }
    }, [location]);

    const handleCloseSnackbar = () => {
        setSnackbarOpen(false);
    };

    const userRole = localStorage.getItem('userRole');



    // Reverting to the "Old Type" look: Smaller banner, "Explore Products" button
    // But keeping functionality clean

    return (
        <Box sx={{ minHeight: '100vh', bgcolor: '#f8fafc' }}>
            <Navbar />

            {/* Wholesale Header & Featured Suppliers Slider */}
            <WholesaleHeader />

            <Container maxWidth="xl" sx={{ mt: 0, mb: 8 }}>


                {
                    view === 'feed' ? (
                        <>
                            {/* Feed */}
                            {userRole === 'Seller' && (
                                <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 2 }}>
                                    <Button
                                        variant="contained"
                                        onClick={() => setView('upload')}
                                        sx={{ bgcolor: 'black', color: 'white', fontWeight: 800, borderRadius: 3, px: 3, '&:hover': { bgcolor: '#333' } }}
                                    >
                                        Post New Product
                                    </Button>
                                </Box>
                            )}
                            <WholesaleFeed key={refreshToken} />
                        </>
                    ) : view === 'upload' ? (
                        <Box sx={{ bgcolor: 'white', borderRadius: 2, p: 4 }}>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                                <Button onClick={handleCancelUpload} startIcon={<CloseIcon />} sx={{ color: '#64748b' }}>Back to Feed</Button>
                            </Box>
                            <WholesaleUploadForm onPost={handleProductPosted} />
                        </Box>
                    ) : (
                        // Requests Feed View
                        <Box>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                                <Button onClick={() => setView('feed')} startIcon={<CloseIcon />} sx={{ color: '#64748b' }}>Back to Feed</Button>
                            </Box>
                            <BuyerRequestsFeed key={refreshToken} />
                        </Box>
                    )
                }
            </Container >

            <Snackbar
                open={snackbarOpen}
                autoHideDuration={6000}
                onClose={handleCloseSnackbar}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
            >
                <Alert onClose={handleCloseSnackbar} severity="success" sx={{ width: '100%' }}>
                    Request posted successfully!
                </Alert>
            </Snackbar>

            <BuyerRequestModal
                open={openRequestDialog}
                onClose={() => setOpenRequestDialog(false)}
                onSubmit={handleRequestSubmit}
            />
            <Footer />
        </Box >
    );
};

export default Wholesale;

import { Box, Typography, Paper, Stack, List, ListItemButton, ListItemIcon, ListItemText, Grid } from '@mui/material';
import DashboardIcon from '@mui/icons-material/Dashboard';
import StoreIcon from '@mui/icons-material/Store';
import WarehouseIcon from '@mui/icons-material/Warehouse';
import FlashOnIcon from '@mui/icons-material/FlashOn';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import WorkOutlineIcon from '@mui/icons-material/WorkOutline';
import ExitToAppIcon from '@mui/icons-material/ExitToApp';
import GroupIcon from '@mui/icons-material/Group';
import ShoppingBagIcon from '@mui/icons-material/ShoppingBag';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import { useNavigate } from 'react-router-dom';
import { AdminService } from '../../../services/api';
import { useEffect, useState } from 'react';

const AdminDashboard = () => {
    const navigate = useNavigate();
    const [statsData, setStatsData] = useState<any>(null);
    const [activities, setActivities] = useState<any>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const { data: stats } = await AdminService.getStats();
                setStatsData(stats);
                const { data: act } = await AdminService.getActivities();
                setActivities(act);
            } catch (error) {
                console.error("Failed to fetch admin data", error);
            }
        };
        fetchStats();
    }, []);

    const menuItems = [
        { name: 'Overview', icon: <DashboardIcon sx={{ fontSize: 20 }} />, path: '/admin/dashboard', active: true },
        { name: 'Retail', icon: <StoreIcon sx={{ fontSize: 20 }} />, path: '/admin/retail' },
        { name: 'Wholesale', icon: <WarehouseIcon sx={{ fontSize: 20 }} />, path: '/admin/wholesale' },
        { name: 'Q-Commerce', icon: <FlashOnIcon sx={{ fontSize: 20 }} />, path: '/admin/quick' },
        { name: 'Resale', icon: <AutorenewIcon sx={{ fontSize: 20 }} />, path: '/admin/resale' },
        { name: 'Freelance', icon: <WorkOutlineIcon sx={{ fontSize: 20 }} />, path: '/admin/freelance' },
    ];

    const stats = [
        {
            title: 'Total User',
            value: statsData?.userCount?.toLocaleString() || '0',
            growth: '+12%',
            icon: <GroupIcon sx={{ color: '#1e293b', fontSize: 22 }} />,
            bgColor: '#f1f5f9'
        },
        {
            title: 'Total Order',
            value: statsData?.orderCount?.toLocaleString() || '0',
            growth: '+8%',
            icon: <ShoppingBagIcon sx={{ color: '#1e293b', fontSize: 22 }} />,
            bgColor: '#f1f5f9'
        },
        {
            title: 'Total Selling Amount',
            value: `Ôé╣${statsData?.totalSales?.toLocaleString() || '0'}`,
            growth: '+24%',
            icon: <AttachMoneyIcon sx={{ color: '#1e293b', fontSize: 22 }} />,
            bgColor: '#f1f5f9'
        }
    ];

    return (
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'white' }}>
            {/* Sidebar */}
            <Box sx={{ width: 260, bgcolor: 'white', borderRight: '1px solid #e2e8f0', p: 3, display: 'flex', flexDirection: 'column', height: '100vh', position: 'sticky', top: 0 }}>
                {/* Logo Area */}
                <Box sx={{ mb: 4 }} />

                <List disablePadding>
                    {menuItems.map((item) => (
                        <ListItemButton
                            key={item.name}
                            onClick={() => item.path !== '/admin/dashboard' && navigate(item.path)}
                            sx={{
                                mb: 1,
                                borderRadius: 3,
                                bgcolor: item.active ? '#CFE8EC' : 'transparent',
                                color: item.active ? '#1e293b' : '#64748b',
                                '&:hover': { bgcolor: item.active ? '#CFE8EC' : '#f8fafc', color: item.active ? '#1e293b' : '#334155' },
                                py: 1.2,
                                px: 2
                            }}
                        >
                            <ListItemIcon sx={{ minWidth: 35, color: item.active ? '#1e293b' : '#64748b' }}>
                                {item.icon}
                            </ListItemIcon>
                            <ListItemText
                                primary={item.name}
                                primaryTypographyProps={{ fontWeight: item.active ? 700 : 500, fontSize: '0.95rem' }}
                            />
                        </ListItemButton>
                    ))}
                </List>

                <Box sx={{ mt: 'auto' }}>
                    <Stack onClick={() => {
                        localStorage.removeItem('token');
                        localStorage.removeItem('userRole');
                        navigate('/admin/login');
                    }} direction="row" alignItems="center" spacing={2} sx={{ px: 2, cursor: 'pointer', color: '#ef4444' }}>
                        <ExitToAppIcon fontSize="small" />
                        <Typography variant="body2" fontWeight={600}>Leave</Typography>
                    </Stack>
                </Box>
            </Box>

            {/* Main Content */}
            <Box sx={{ flexGrow: 1, p: 4, overflow: 'auto', bgcolor: '#f8fafc' }}>
                <Box sx={{ mb: 2 }} />

                {/* Stats Cards */}
                <Grid container spacing={4} sx={{ mb: 5 }}>
                    {stats.map((stat, index) => (
                        <Grid key={index} size={{ xs: 12, md: 4 }}>
                            <Paper
                                elevation={0}
                                sx={{
                                    p: 3,
                                    borderRadius: 4,
                                    bgcolor: 'white',
                                    boxShadow: '0 4px 20px rgba(0,0,0,0.02)',
                                    display: 'flex',
                                    justifyContent: 'space-between',
                                    alignItems: 'flex-start',
                                    height: '100%'
                                }}
                            >
                                <Box>
                                    <Typography variant="body2" sx={{ color: '#64748b', fontWeight: 600, mb: 1.5 }}>{stat.title}</Typography>
                                    <Stack direction="row" alignItems="center" spacing={1.5}>
                                        <Typography variant="h4" sx={{ fontWeight: 800, color: '#1e293b' }}>{stat.value}</Typography>
                                        <Typography variant="caption" sx={{ color: '#166534', fontWeight: 800, bgcolor: '#dcfce7', px: 1, py: 0.3, borderRadius: 1.5 }}>{stat.growth}</Typography>
                                    </Stack>
                                </Box>
                                <Box sx={{ bgcolor: '#f1f5f9', p: 1.2, borderRadius: 2, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                    {stat.icon}
                                </Box>
                            </Paper>
                        </Grid>
                    ))}
                </Grid>

                <Grid container spacing={4}>
                    <Grid size={{ xs: 12, md: 8 }}>
                        {/* Recent Activity Table */}
                        <Paper elevation={0} sx={{ p: 4, borderRadius: 4, bgcolor: 'white', boxShadow: '0 4px 20px rgba(0,0,0,0.02)', mb: 4 }}>
                            <Typography variant="h6" sx={{ fontWeight: 800, mb: 3 }}>Recent Activity</Typography>
                            <Box>
                                {activities?.recentOrders?.map((order: any) => (
                                    <Stack key={order._id} direction="row" justifyContent="space-between" alignItems="center" sx={{ py: 2, borderBottom: '1px solid #f1f5f9' }}>
                                        <Stack direction="row" spacing={2} alignItems="center">
                                            <Box sx={{ width: 42, height: 42, bgcolor: '#f1f5f9', borderRadius: 2, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                <ShoppingBagIcon sx={{ color: '#1e293b', fontSize: 20, opacity: 0.7 }} />
                                            </Box>
                                            <Box>
                                                <Typography variant="body2" sx={{ fontWeight: 700, color: '#1e293b' }}>Order from {order.user?.username || 'Guest'}</Typography>
                                                <Typography variant="caption" sx={{ color: '#64748b', fontWeight: 600 }}>ID: {order._id.substring(0, 8).toUpperCase()}</Typography>
                                            </Box>
                                        </Stack>
                                        <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>Ôé╣{order.totalPrice}</Typography>
                                    </Stack>
                                ))}
                                {(!activities?.recentOrders || activities.recentOrders.length === 0) && (
                                    <Typography variant="body2" color="textSecondary">No recent activity found.</Typography>
                                )}
                            </Box>
                        </Paper>
                    </Grid>

                    <Grid size={{ xs: 12, md: 4 }}>
                        {/* Segment Breakdown */}
                        <Paper elevation={0} sx={{ p: 4, borderRadius: 4, bgcolor: 'white', boxShadow: '0 4px 20px rgba(0,0,0,0.02)' }}>
                            <Typography variant="h6" sx={{ fontWeight: 800, mb: 3 }}>Segments Activity</Typography>
                            <Stack spacing={3}>
                                {[
                                    { label: 'Retail Products', value: statsData?.segments?.retail, icon: <StoreIcon sx={{ fontSize: 18 }} />, color: '#22c55e' },
                                    { label: 'Wholesale Items', value: statsData?.segments?.wholesale, icon: <WarehouseIcon sx={{ fontSize: 18 }} />, color: '#3b82f6' },
                                    { label: 'Q-Commerce', value: statsData?.segments?.qCommerce, icon: <FlashOnIcon sx={{ fontSize: 18 }} />, color: '#eab308' },
                                    { label: 'Resale Items', value: statsData?.segments?.resale, icon: <AutorenewIcon sx={{ fontSize: 18 }} />, color: '#6366f1' },
                                    { label: 'Freelance Posts', value: statsData?.segments?.freelance, icon: <WorkOutlineIcon sx={{ fontSize: 18 }} />, color: '#d946ef' },
                                ].map((seg, i) => (
                                    <Stack key={i} direction="row" alignItems="center" spacing={2} sx={{ py: 0.5 }}>
                                        <Box sx={{ color: seg.color }}>{seg.icon}</Box>
                                        <Box sx={{ flexGrow: 1 }}>
                                            <Typography variant="caption" sx={{ fontWeight: 700, color: '#334155' }}>{seg.label}</Typography>
                                            <Box sx={{ width: '100%', height: 4, bgcolor: '#f1f5f9', borderRadius: 1, mt: 0.5 }}>
                                                <Box sx={{ width: `${Math.min(100, (seg.value || 0) * 10)}%`, height: '100%', bgcolor: seg.color, borderRadius: 1 }} />
                                            </Box>
                                        </Box>
                                        <Typography variant="body2" sx={{ fontWeight: 800, color: '#1e293b' }}>{seg.value || 0}</Typography>
                                    </Stack>
                                ))}
                            </Stack>
                        </Paper>
                    </Grid>
                </Grid>
            </Box>
        </Box >
    );
};

export default AdminDashboard;

import { useEffect, useState } from 'react';
import { Box, Typography, Paper, Stack, IconButton, List, ListItemButton, ListItemIcon, ListItemText, Grid, Chip, Avatar, CircularProgress, Tabs, Tab, Button, Link } from '@mui/material';
import { toast } from 'react-toastify';
import DashboardIcon from '@mui/icons-material/Dashboard';
import StoreIcon from '@mui/icons-material/Store';
import WarehouseIcon from '@mui/icons-material/Warehouse';
import FlashOnIcon from '@mui/icons-material/FlashOn';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import WorkOutlineIcon from '@mui/icons-material/WorkOutline';
import ExitToAppIcon from '@mui/icons-material/ExitToApp';
import DeleteIcon from '@mui/icons-material/Delete';
import CheckIcon from '@mui/icons-material/Check';
import CloseIcon from '@mui/icons-material/Close';
import { useNavigate } from 'react-router-dom';
import { FreelanceService, AdminService } from '../../../services/api';

const FreelanceManagement = () => {
    const navigate = useNavigate();
    const [posts, setPosts] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [tab, setTab] = useState(0);
    const [pendingFreelancers, setPendingFreelancers] = useState<any[]>([]);
    const [verifiedFreelancers, setVerifiedFreelancers] = useState<any[]>([]);
    const [interests, setInterests] = useState<any[]>([]);

    useEffect(() => {
        fetchPosts();
        fetchPendingFreelancers();
        fetchVerifiedFreelancers();
        fetchInterests();
    }, []);

    const fetchPosts = async () => {
        try {
            const { data } = await FreelanceService.getAll();
            setPosts(data);
        } catch (error) {
            console.error("Failed to fetch freelance posts", error);
        } finally {
            setIsLoading(false);
        }
    };

    const fetchPendingFreelancers = async () => {
        try {
            const { data } = await AdminService.getPendingFreelancers();
            setPendingFreelancers(data);
        } catch (error) {
            console.error("Failed to fetch pending freelancers", error);
        }
    };

    const fetchVerifiedFreelancers = async () => {
        try {
            const { data } = await AdminService.getVerifiedFreelancers();
            setVerifiedFreelancers(data);
        } catch (error) {
            console.error("Failed to fetch verified freelancers", error);
        }
    };

    const fetchInterests = async () => {
        try {
            const { data } = await AdminService.getInterests();
            setInterests(data);
        } catch (error) {
            console.error("Failed to fetch freelance interests", error);
        }
    };

    const handleFreelancerStatus = async (id: string, status: string) => {
        try {
            await AdminService.updateFreelancerStatus(id, status);
            setPendingFreelancers(pendingFreelancers.filter(f => f._id !== id));
            toast.success(`Freelancer ${status} successfully`);
        } catch (error) {
            toast.error("Failed to update status");
        }
    };

    const handleInterestStatus = async (id: string, status: string) => {
        try {
            await AdminService.updateInterestStatus(id, status);
            setInterests(interests.map(i => i._id === id ? { ...i, status } : i));
            toast.success(`Interest request ${status} successfully`);
        } catch (error) {
            toast.error("Failed to update interest status");
        }
    };

    const handleUpdateStatus = async (id: string, status: string) => {
        try {
            await FreelanceService.updateStatus(id, status);
            setPosts(posts.map(p => p._id === id ? { ...p, status } : p));
            toast.success(`Post ${status} successfully`);
        } catch (error) {
            toast.error("Failed to update post status");
        }
    };

    const handleDelete = async (id: string) => {
        if (window.confirm("Delete this freelance post?")) {
            try {
                await FreelanceService.delete(id);
                setPosts(posts.filter(p => p._id !== id));
                toast.success("Post deleted successfully");
            } catch (error) {
                toast.error("Failed to delete post");
            }
        }
    };

    const menuItems = [
        { name: 'Overview', icon: <DashboardIcon />, path: '/admin/dashboard' },
        { name: 'Retail', icon: <StoreIcon />, path: '/admin/retail' },
        { name: 'Wholesale', icon: <WarehouseIcon />, path: '/admin/wholesale' },
        { name: 'Q-Commerce', icon: <FlashOnIcon />, path: '/admin/quick' },
        { name: 'Resale', icon: <AutorenewIcon />, path: '/admin/resale' },
        { name: 'Freelance', icon: <WorkOutlineIcon />, path: '/admin/freelance', active: true },
    ];

    return (
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: '#f8fafc' }}>
            {/* Sidebar */}
            <Box sx={{ width: 260, bgcolor: 'white', borderRight: '1px solid #e2e8f0', p: 3, display: 'flex', flexDirection: 'column', height: '100vh', position: 'sticky', top: 0 }}>
                <Stack direction="row" alignItems="center" spacing={1.5} sx={{ mb: 5, px: 2 }}>
                    <Box sx={{ bgcolor: '#B4D5DC', p: 0.5, borderRadius: 1, display: 'flex' }}>
                        <WorkOutlineIcon sx={{ color: 'black' }} />
                    </Box>
                    <Typography variant="h6" sx={{ fontWeight: 800 }}>freelance</Typography>
                </Stack>

                <List disablePadding>
                    {menuItems.map((item) => (
                        <ListItemButton
                            key={item.name}
                            onClick={() => item.path !== '/admin/freelance' && navigate(item.path)}
                            sx={{
                                mb: 1,
                                borderRadius: 3,
                                bgcolor: item.active ? '#B4D5DC' : 'transparent',
                                color: item.active ? 'black' : '#64748b',
                                '&:hover': { bgcolor: item.active ? '#B4D5DC' : '#f1f5f9' },
                                py: 1.5
                            }}
                        >
                            <ListItemIcon sx={{ minWidth: 40, color: item.active ? 'black' : '#94a3b8' }}>
                                {item.icon}
                            </ListItemIcon>
                            <ListItemText
                                primary={item.name}
                                primaryTypographyProps={{ fontWeight: item.active ? 700 : 500, fontSize: '0.95rem' }}
                            />
                        </ListItemButton>
                    ))}
                </List>

                <Box sx={{ mt: 'auto' }}>
                    <Stack onClick={() => { localStorage.removeItem('token'); localStorage.removeItem('userRole'); navigate('/admin/login'); }} direction="row" alignItems="center" spacing={2} sx={{ px: 2, cursor: 'pointer', color: '#ef4444' }}>
                        <ExitToAppIcon fontSize="small" />
                        <Typography variant="body2" fontWeight={600}>Leave</Typography>
                    </Stack>
                </Box>
            </Box>

            {/* Main Content */}
            <Box sx={{ flexGrow: 1, p: 4, overflow: 'auto' }}>
                <Typography variant="h4" sx={{ fontWeight: 800, mb: 4 }}>Freelance Posts Management</Typography>

                <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
                    <Tabs value={tab} onChange={(_, v) => setTab(v)}>
                        <Tab label="Freelance Posts" />
                        <Tab label="Verification Requests" />
                        <Tab label="Verified Freelancers" />
                        <Tab label="Interest Requests" />
                    </Tabs>
                </Box>

                {isLoading ? (
                    <Box sx={{ display: 'flex', justifyContent: 'center', p: 5 }}><CircularProgress sx={{ color: '#B4D5DC' }} /></Box>
                ) : (
                    <>
                        {tab === 0 && (
                            <Grid container spacing={3}>
                                {posts.map((post) => (
                                    <Grid size={{ xs: 12, sm: 12, md: 6 }} key={post._id}>
                                        <Paper sx={{ p: 3, bgcolor: 'white', borderRadius: 3, height: '100%', display: 'flex', flexDirection: 'column', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}>
                                            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 2 }}>
                                                <Chip label={post.category || 'General'} size="small" sx={{ bgcolor: '#f1f5f9', color: '#64748b', fontWeight: 700, fontSize: '0.65rem', borderRadius: 1 }} />
                                                <Chip
                                                    label={post.status || 'NEW'}
                                                    size="small"
                                                    sx={{
                                                        bgcolor: post.status === 'APPROVED' ? '#ecfccb' : post.status === 'REJECTED' ? '#fef2f2' : '#eff6ff',
                                                        color: post.status === 'APPROVED' ? '#84cc16' : post.status === 'REJECTED' ? '#ef4444' : '#3b82f6',
                                                        fontWeight: 800,
                                                        fontSize: '0.65rem',
                                                        borderRadius: 1
                                                    }}
                                                />
                                            </Stack>

                                            {post.image && (
                                                <Box component="img" src={post.image} sx={{ width: '100%', height: 160, objectFit: 'cover', borderRadius: 2, mb: 2 }} />
                                            )}

