                                        <Paper sx={{ p: 3, bgcolor: 'white', borderRadius: 3, height: '100%', display: 'flex', flexDirection: 'column', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}>
                                            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 2 }}>
                                                <Typography variant="overline" sx={{ fontWeight: 800, color: '#64748b' }}>Interest Request</Typography>
                                                <Chip
                                                    label={interest.status || 'Pending'}
                                                    size="small"
                                                    sx={{
                                                        bgcolor: interest.status === 'Approved' ? '#ecfccb' : interest.status === 'Rejected' ? '#fef2f2' : '#f1f5f9',
                                                        color: interest.status === 'Approved' ? '#84cc16' : interest.status === 'Rejected' ? '#ef4444' : '#64748b',
                                                        fontWeight: 800, borderRadius: 1, fontSize: '0.65rem'
                                                    }}
                                                />
                                            </Stack>

                                            <Box sx={{ mb: 2 }}>
                                                <Typography variant="body2" sx={{ color: '#94a3b8' }}>Post Title:</Typography>
                                                <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>{interest.post?.title || 'Unknown Post'}</Typography>
                                            </Box>

                                            <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2, p: 2, bgcolor: '#f8fafc', borderRadius: 2 }}>
                                                <Avatar sx={{ width: 40, height: 40 }}>{interest.user?.profile?.name?.[0] || interest.user?.username?.[0]}</Avatar>
                                                <Box>
                                                    <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>{interest.user?.profile?.name || interest.user?.username}</Typography>
                                                    <Typography variant="caption" sx={{ color: '#64748b', display: 'block', fontWeight: 600 }}>ID: {interest.user?.freelancer?.freelancerId || interest.user?._id}</Typography>
                                                    <Typography variant="caption" sx={{ color: '#84cc16', display: 'block', fontSize: '0.7rem', fontWeight: 700 }}>{interest.user?.freelancer?.category || 'No Category'}</Typography>
                                                    <Typography variant="caption" sx={{ color: '#94a3b8' }}>{interest.user?.email}</Typography>
                                                </Box>
                                            </Stack>

                                            <Box sx={{ mb: 2, p: 2, bgcolor: '#fffbed', borderRadius: 2, border: '1px solid #fef3c7' }}>
                                                <Typography variant="caption" sx={{ fontWeight: 800, color: '#b45309', display: 'block', mb: 1, textTransform: 'uppercase', letterSpacing: 0.5 }}>Proposal Details</Typography>
                                                <Stack direction="row" justifyContent="space-between" sx={{ mb: 0.5 }}>
                                                    <Typography variant="body2" sx={{ color: '#78350f', fontWeight: 600 }}>Proposed Price:</Typography>
                                                    <Typography variant="body2" sx={{ fontWeight: 800, color: '#000' }}>Ôé╣{interest.proposedPrice || 0}</Typography>
                                                </Stack>
                                                <Stack direction="row" justifyContent="space-between">
                                                    <Typography variant="body2" sx={{ color: '#78350f', fontWeight: 600 }}>Est. Duration:</Typography>
                                                    <Typography variant="body2" sx={{ fontWeight: 800, color: '#000' }}>{interest.estimatedDuration || 'N/A'}</Typography>
                                                </Stack>
                                            </Box>

                                            {interest.status === 'Pending' && (
                                                <Stack direction="row" spacing={2} sx={{ mt: 'auto' }}>
                                                    <Button
                                                        variant="contained"
                                                        color="success"
                                                        size="small"
                                                        onClick={() => handleInterestStatus(interest._id, 'Approved')}
                                                        fullWidth
                                                        sx={{ py: 1, fontWeight: 700 }}
                                                    >
                                                        Approve
                                                    </Button>
                                                    <Button
                                                        variant="contained"
                                                        color="error"
                                                        size="small"
                                                        onClick={() => handleInterestStatus(interest._id, 'Rejected')}
                                                        fullWidth
                                                        sx={{ py: 1, fontWeight: 700 }}
                                                    >
                                                        Reject
                                                    </Button>
                                                </Stack>
                                            )}
                                        </Paper>
                                    </Grid>
                                ))}
                                {interests.length === 0 && <Typography sx={{ m: 2 }}>No interest requests found.</Typography>}
                            </Grid>
                        )}
                    </>
                )}
            </Box>
        </Box>
    );
};

export default FreelanceManagement;

import { useEffect, useState } from 'react';
import {
    Box,
    Typography,
    Paper,
    Stack,
    List,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    Button,
    TextField,
    InputAdornment,
    Grid,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    LinearProgress,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    CircularProgress,
    MenuItem,
    Chip,
    IconButton
} from '@mui/material';

import DashboardIcon from '@mui/icons-material/Dashboard';
import StoreIcon from '@mui/icons-material/Store';
import WarehouseIcon from '@mui/icons-material/Warehouse';
import FlashOnIcon from '@mui/icons-material/FlashOn';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import WorkOutlineIcon from '@mui/icons-material/WorkOutline';
import ExitToAppIcon from '@mui/icons-material/ExitToApp';
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/Add';
import RefreshIcon from '@mui/icons-material/Refresh';
import ElectricBoltIcon from '@mui/icons-material/ElectricBolt';
import ThemeIcon from '@mui/icons-material/Brightness4';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import { useNavigate } from 'react-router-dom';
import { QProductService, OrderService, UploadService } from '../../../services/api';
import { toast } from 'react-toastify';

const QCommerceManagement = () => {
    const navigate = useNavigate();
    const [products, setProducts] = useState<any[]>([]);
    const [orders, setOrders] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');

    // Create Product Modal State (Retail-like)
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState<any>(null);
    const [newProduct, setNewProduct] = useState({
        title: '',
        brand: '',
        category: '',
        price: '',
        mrp: '',
        discount: '',
        stock: '',
        unit: '',
        description: '',
        images: '' // comma separated URLs
    });
    const [isUploading, setIsUploading] = useState(false);
    const [isCreating, setIsCreating] = useState(false);

    useEffect(() => {
        fetchProducts();
        fetchOrders();
    }, []);

    const fetchProducts = async () => {
        try {
            const { data } = await QProductService.getAll();
            setProducts(data);
        } catch (error) {
            console.error("Failed to fetch Q-commerce products", error);
        } finally {
            setIsLoading(false);
        }
    };

    const fetchOrders = async () => {
        try {
            const { data } = await OrderService.getAll();
            // Filter or just use all orders for now
            setOrders(data);
        } catch (error) {
            console.error("Failed to fetch orders", error);
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        setIsUploading(true);
        try {
            const uploadPromises = Array.from(files).map(async (file) => {
                const { data } = await UploadService.uploadImage(file);
                return data.url;
            });
            const uploadedUrls = await Promise.all(uploadPromises);

            setNewProduct(prev => {
                const existingImages = prev.images
                    ? prev.images.split(',').map((img: string) => img.trim()).filter((img: string) => img !== '')
                    : [];
                const nextImages = [...existingImages, ...uploadedUrls];
                return { ...prev, images: nextImages.join(', ') };
            });
            toast.success(`${uploadedUrls.length} image(s) uploaded successfully!`);
        } catch (error: any) {
            toast.error(`Upload failed: ${error.response?.data?.message || error.message}`);
        } finally {
            setIsUploading(false);
        }
    };

    const removeImage = (urlToRemove: string) => {
        setNewProduct(prev => {
            const currentImages = prev.images
                .split(',')
                .map((img: string) => img.trim())
                .filter((img: string) => img !== '');
            const filteredImages = currentImages.filter((url: string) => url !== urlToRemove);
            return { ...prev, images: filteredImages.join(', ') };
        });
    };

    const handleDeleteProduct = async (id: string) => {
        if (window.confirm("Delete this Q-Commerce product?")) {
            try {
                await QProductService.delete(id);
                setProducts(products.filter((p: any) => p._id !== id));
                toast.success("Product deleted successfully");
            } catch (error) {
                toast.error("Failed to delete product");
            }
        }
    };

    const handleEditProduct = (product: any) => {
        setEditingProduct(product);
        setNewProduct({
            title: product.title || '',
            brand: product.brand || '',
            category: product.category || '',
            price: product.price?.toString() || '',
            mrp: product.mrp?.toString() || '',
            discount: product.discount?.toString() || '',
            stock: product.stock?.toString() || '',
            unit: product.unit || '',
            description: product.description || '',
            images: Array.isArray(product.images) ? product.images.join(', ') : (product.image || '')
        });
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingProduct(null);
        setNewProduct({
            title: '', brand: '', category: '', price: '', mrp: '', discount: '', stock: '', unit: '', description: '', images: ''
        });
    };

    const handleUpdateProduct = async () => {
        if (!editingProduct) return;

        // Validate required fields
        if (!newProduct.title.trim()) {
            toast.error('Product title is required');
            return;
        }
        if (!newProduct.brand.trim()) {
            toast.error('Brand is required');
            return;
        }
        if (!newProduct.category.trim()) {
            toast.error('Category is required');
            return;
        }
        if (!newProduct.price || Number(newProduct.price) <= 0) {
            toast.error('Valid price is required');
            return;
        }
        if (!newProduct.mrp || Number(newProduct.mrp) <= 0) {
            toast.error('Valid MRP is required');
            return;
        }

        setIsCreating(true);
        try {
            const images = newProduct.images
                .split(',')
                .map((img: string) => img.trim())
                .filter((img: string) => img !== '');

            const payload = {
                title: newProduct.title.trim(),
                brand: newProduct.brand.trim(),
                category: newProduct.category.trim(),
                price: Number(newProduct.price),
                mrp: Number(newProduct.mrp),
                discount: newProduct.discount === '' ? 0 : Number(newProduct.discount),
                stock: newProduct.stock === '' ? 0 : Number(newProduct.stock),
                unit: newProduct.unit.trim() || undefined,
                description: newProduct.description.trim() || undefined,
                image: images[0] || 'https://via.placeholder.com/600',
                images
            };

            const { data } = await QProductService.update(editingProduct._id, payload);
            setProducts(products.map((p: any) => p._id === editingProduct._id ? data : p));
            handleCloseModal();
            toast.success('Product updated successfully!');
        } catch (error: any) {
            console.error('Failed to update product:', error);
            toast.error(`Failed to update: ${error.response?.data?.message || error.message}`);
        } finally {
            setIsCreating(false);
        }
    };

    const handleCreateProduct = async () => {
        // Validate required fields
        if (!newProduct.title.trim()) {
            toast.error('Product title is required');
            return;
        }
        if (!newProduct.brand.trim()) {
            toast.error('Brand is required');
            return;
        }
        if (!newProduct.category.trim()) {
            toast.error('Category is required');
            return;
        }
        if (!newProduct.price || Number(newProduct.price) <= 0) {
            toast.error('Valid price is required');
            return;
        }
        if (!newProduct.mrp || Number(newProduct.mrp) <= 0) {
            toast.error('Valid MRP is required');
            return;
        }

        setIsCreating(true);
        try {
            const images = newProduct.images
                .split(',')
                .map((img: string) => img.trim())
                .filter((img: string) => img !== '');

            const payload = {
                title: newProduct.title.trim(),
                brand: newProduct.brand.trim(),
                category: newProduct.category.trim(),
                price: Number(newProduct.price),
                mrp: Number(newProduct.mrp),
                discount: newProduct.discount === '' ? 0 : Number(newProduct.discount),
                stock: newProduct.stock === '' ? 0 : Number(newProduct.stock),
                unit: newProduct.unit.trim() || undefined,
                description: newProduct.description.trim() || undefined,
                image: images[0] || 'https://via.placeholder.com/600',
                images
            };

            const { data } = await QProductService.create(payload);
            setProducts([data, ...products]);
            handleCloseModal();
            toast.success('Q-Commerce product created successfully!');
        } catch (error: any) {
            console.error('Failed to create Q-Commerce product:', error);
            toast.error(`Failed to create: ${error.response?.data?.message || error.message}`);
        } finally {
            setIsCreating(false);
        }
    };

    const menuItems = [
        { name: 'Overview', icon: <DashboardIcon sx={{ fontSize: 20 }} />, path: '/admin/dashboard' },
        { name: 'Retail', icon: <StoreIcon sx={{ fontSize: 20 }} />, path: '/admin/retail' },
        { name: 'Wholesale', icon: <WarehouseIcon sx={{ fontSize: 20 }} />, path: '/admin/wholesale' },
        { name: 'Q-Commerce', icon: <FlashOnIcon sx={{ fontSize: 20 }} />, path: '/admin/quick', active: true },
        { name: 'Resale', icon: <AutorenewIcon sx={{ fontSize: 20 }} />, path: '/admin/resale' },
        { name: 'Freelance', icon: <WorkOutlineIcon sx={{ fontSize: 20 }} />, path: '/admin/freelance' },
    ];



    return (
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'white' }}>
            {/* Sidebar */}
            <Box sx={{ width: 260, bgcolor: 'white', borderRight: '1px solid #f1f5f9', p: 3, display: 'flex', flexDirection: 'column', height: '100vh', position: 'sticky', top: 0 }}>
                <Stack direction="row" alignItems="center" spacing={1.5} sx={{ mb: 5, px: 1 }}>
                    <Box sx={{ bgcolor: 'black', p: 0.8, borderRadius: 1.5, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Box component="span" sx={{ color: 'white', fontWeight: 900, fontSize: '1.2rem', lineHeight: 1 }}>R</Box>
                    </Box>
                    <Typography variant="h6" sx={{ fontWeight: 800, fontSize: '1.25rem', color: '#1e293b' }}>retails</Typography>
                </Stack>

                <List disablePadding sx={{ flexGrow: 1 }}>
                    {menuItems.map((item) => (
                        <ListItemButton
                            key={item.name}
                            onClick={() => !item.active && navigate(item.path)}
                            sx={{
                                mb: 1,
                                borderRadius: 3,
                                bgcolor: item.active ? '#B4D5DC' : 'transparent',
                                color: item.active ? 'black' : '#64748b',
                                '&:hover': { bgcolor: item.active ? '#B4D5DC' : '#f8fafc' },
                                py: 1.2,
                                px: 2
                            }}
                        >
                            <ListItemIcon sx={{ minWidth: 35, color: item.active ? 'black' : '#64748b' }}>
                                {item.icon}
                            </ListItemIcon>
                            <ListItemText
                                primary={item.name}
                                primaryTypographyProps={{ fontWeight: item.active ? 700 : 500, fontSize: '0.95rem' }}
                            />
                        </ListItemButton>
                    ))}
                </List>

                <Box sx={{ mt: 'auto', pt: 2 }}>

                    <Stack onClick={() => { localStorage.removeItem('token'); localStorage.removeItem('userRole'); navigate('/admin/login'); }} direction="row" alignItems="center" spacing={2} sx={{ px: 2, cursor: 'pointer', color: '#ef4444' }}>
                        <ExitToAppIcon sx={{ fontSize: 20 }} />
                        <Typography variant="body2" fontWeight={600}>Leave</Typography>
                    </Stack>
                </Box>
            </Box>

            {/* Main Content */}
            <Box sx={{ flexGrow: 1, p: 4, bgcolor: '#f8fafc', overflow: 'auto' }}>
                {/* Header */}
                <Stack direction="row" justifyContent="space-between" alignItems="flex-start" sx={{ mb: 4 }}>
                    <Box>
                        <Typography variant="h4" sx={{ fontWeight: 800, color: '#1e293b', mb: 0.5 }}>Q-Commerce Inventory</Typography>
                        <Typography variant="body2" sx={{ color: '#64748b', fontWeight: 500 }}>Real-time rapid delivery management</Typography>
                    </Box>
                    <Stack direction="row" spacing={2}>

                        <Button
                            variant="contained"
                            startIcon={<AddIcon />}
                            onClick={() => {
                                handleCloseModal(); // Reset state for new product
                                setIsModalOpen(true);
                            }}
                            sx={{
                                bgcolor: '#B4D5DC',
                                color: 'black',
                                borderRadius: 3,
                                px: 3,
                                fontWeight: 700,
                                textTransform: 'none',
                                boxShadow: 'none',
                                '&:hover': { bgcolor: '#9cc8d1', boxShadow: 'none' }
                            }}
                        >
                            Create Entry
                        </Button>
                    </Stack>
                </Stack>

                {/* Stats Cards */}
                <Grid container spacing={3} sx={{ mb: 6 }}>
                    <Grid size={{ xs: 12, md: 6 }}>
                        <Paper elevation={0} sx={{ p: 3, borderRadius: 5, bgcolor: 'white', display: 'flex', alignItems: 'center' }}>
                            <Box sx={{ p: 1, bgcolor: '#f1f5f9', borderRadius: 2 }}><StoreIcon sx={{ color: '#3b82f6' }} /></Box>
                            <Box sx={{ ml: 2 }}>
                                <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700, display: 'block', mb: 0.5 }}>Total Products</Typography>
                                <Typography variant="h4" sx={{ fontWeight: 900, color: '#1e293b' }}>{products.length}</Typography>
                            </Box>
                        </Paper>
                    </Grid>
                    <Grid size={{ xs: 12, md: 6 }}>
                        <Paper elevation={0} sx={{ p: 3, borderRadius: 5, bgcolor: 'white', display: 'flex', alignItems: 'center' }}>
                            <Box sx={{ p: 1, bgcolor: '#f0fdf4', borderRadius: 2 }}><ElectricBoltIcon sx={{ color: '#22c55e' }} /></Box>
                            <Box sx={{ ml: 2 }}>
                                <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700, display: 'block', mb: 0.5 }}>Total Orders</Typography>
                                <Typography variant="h4" sx={{ fontWeight: 900, color: '#1e293b' }}>{orders.length}</Typography>
                            </Box>
                        </Paper>
                    </Grid>
                </Grid>

                {/* Instant Inventory */}
                <Box sx={{ mb: 6 }}>
                    <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 3 }}>
                        <Stack direction="row" alignItems="center" spacing={2}>
                            <Typography variant="h6" sx={{ fontWeight: 800, color: '#1e293b' }}>Instant Inventory</Typography>
                            <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700 }}>{products.length} Items</Typography>
                        </Stack>
                        <Button onClick={fetchProducts} startIcon={<RefreshIcon />} sx={{ color: '#94a3b8', textTransform: 'none', fontWeight: 700 }}>Refresh Feed</Button>
                    </Stack>

                    <Grid container spacing={3}>
                        {(products.length > 0 ? products : [])
                            .filter((p: any) =>
                                !searchQuery
                                    ? true
                                    : String(p.title || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
                                    String(p.category || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
                                    String(p.brand || '').toLowerCase().includes(searchQuery.toLowerCase())
                            )
                            .map((item, i) => (
                                <Grid key={item._id || i} size={{ xs: 12, sm: 6, md: 3 }}>
                                    <Paper elevation={0} sx={{ borderRadius: 5, overflow: 'hidden', bgcolor: 'white', border: '1px solid #f1f5f9', height: '100%', display: 'flex', flexDirection: 'column' }}>
                                        <Box sx={{ position: 'relative', height: 180 }}>
                                            <Box component="img" src={item.image || 'https://via.placeholder.com/300'} sx={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                            <Box sx={{ position: 'absolute', top: 12, left: 12, bgcolor: '#22c55e', px: 1, py: 0.5, borderRadius: 1.5 }}>
                                                <Typography sx={{ color: 'white', fontSize: '0.65rem', fontWeight: 900 }}>INSTOCK</Typography>
                                            </Box>
                                        </Box>
                                        <Box sx={{ p: 2.5, flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                                            <Typography variant="subtitle1" sx={{ fontWeight: 800, color: '#1e293b', mb: 0.5 }}>{item.title}</Typography>
                                            <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700, display: 'block', mb: 2 }}>{item.category}</Typography>

                                            <Stack spacing={2} sx={{ mb: 3, mt: 'auto' }}>
                                                <Box>
                                                    <Stack direction="row" justifyContent="space-between" sx={{ mb: 0.5 }}>
                                                        <Typography variant="caption" sx={{ color: '#64748b', fontWeight: 600 }}>Stock Level</Typography>
                                                        <Typography variant="caption" sx={{ color: '#1e293b', fontWeight: 800 }}>{item.stock || 'N/A'}</Typography>
                                                    </Stack>
                                                    <LinearProgress variant="determinate" value={item.stock ? Math.min(100, item.stock) : 50} sx={{ height: 6, borderRadius: 3, bgcolor: '#f1f5f9', '& .MuiLinearProgress-bar': { bgcolor: '#22c55e', borderRadius: 3 } }} />
                                                </Box>
                                                <Box>
                                                    <Stack direction="row" justifyContent="space-between" alignItems="center">
                                                        <Typography variant="caption" sx={{ color: '#64748b', fontWeight: 600 }}>Price: Ôé╣{item.price}</Typography>
                                                        <Stack direction="row" spacing={0.5}>
                                                            <IconButton size="small" onClick={() => handleEditProduct(item)} sx={{ color: '#94a3b8', '&:hover': { color: '#1e293b', bgcolor: '#f1f5f9' } }}>
                                                                <EditIcon fontSize="small" />
                                                            </IconButton>
                                                            <IconButton size="small" onClick={() => handleDeleteProduct(item._id)} sx={{ color: '#fee2e2', '&:hover': { color: '#ef4444', bgcolor: '#fef2f2' } }}>
                                                                <DeleteIcon fontSize="small" />
                                                            </IconButton>
                                                        </Stack>
                                                    </Stack>
                                                </Box>
                                            </Stack>
                                        </Box>
                                    </Paper>
                                </Grid>
                            ))}
                        {products.length === 0 && <Typography sx={{ p: 2, color: '#94a3b8' }}>No inventory items found.</Typography>}
                    </Grid>
                </Box>

                {/* Live Order Feed */}
                <Box>
                    <Stack direction="row" alignItems="center" spacing={2} sx={{ mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 800, color: '#1e293b' }}>Live Order Feed</Typography>
                        <Stack direction="row" alignItems="center" spacing={1}>
                            <Box sx={{ width: 8, height: 8, bgcolor: '#22c55e', borderRadius: '50%' }} />
                            <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700 }}>Tracking {orders.length} active orders</Typography>
                        </Stack>
                    </Stack>

                    <TableContainer component={Paper} elevation={0} sx={{ borderRadius: 5, border: '1px solid #f1f5f9' }}>
                        <Table>
                            <TableHead sx={{ bgcolor: '#fcfdfe' }}>
                                <TableRow>
                                    <TableCell sx={{ color: '#94a3b8', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase', py: 2.5 }}>Order ID</TableCell>
                                    <TableCell sx={{ color: '#94a3b8', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase' }}>Items</TableCell>
                                    <TableCell sx={{ color: '#94a3b8', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase' }}>Total Amount</TableCell>
                                    <TableCell sx={{ color: '#94a3b8', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase' }}>Date</TableCell>
                                    <TableCell sx={{ color: '#94a3b8', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase', textAlign: 'right' }}>Status</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {orders.map((order, i) => (
                                    <TableRow key={i} sx={{ '&:last-child td': { border: 0 } }}>
                                        <TableCell sx={{ fontWeight: 800, color: '#64748b', fontSize: '0.85rem' }}>{order._id}</TableCell>
                                        <TableCell>
                                            <Typography variant="body2" sx={{ fontWeight: 800, color: '#1e293b' }}>
                                                {order.items?.length || 0} Items
                                            </Typography>
                                        </TableCell>
                                        <TableCell sx={{ color: '#64748b', fontWeight: 600, fontSize: '0.85rem' }}>Ôé╣{order.totalAmount}</TableCell>
                                        <TableCell sx={{ color: '#1e293b', fontWeight: 800, fontSize: '0.85rem' }}>{new Date(order.createdAt).toLocaleDateString()}</TableCell>
                                        <TableCell sx={{ textAlign: 'right' }}>
                                            <Box sx={{ display: 'inline-block', bgcolor: '#f8fafc', px: 1.5, py: 0.5, borderRadius: 2 }}>
                                                <Typography sx={{ color: '#1e293b', fontWeight: 900, fontSize: '0.65rem' }}>{order.status}</Typography>
                                            </Box>
                                        </TableCell>
                                    </TableRow>
                                ))}
                                {orders.length === 0 && (
                                    <TableRow>
                                        <TableCell colSpan={5} sx={{ textAlign: 'center', color: '#94a3b8', py: 3 }}>No recent orders found.</TableCell>
                                    </TableRow>
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </Box>

                {/* Create Q-Commerce Product Modal (Retail-like) */}
                <Dialog
                    open={isModalOpen}
                    onClose={handleCloseModal}
                    maxWidth="sm"
                    fullWidth
                    PaperProps={{ sx: { borderRadius: 6, p: 1 } }}
                >
                    <DialogTitle sx={{ fontWeight: 900, fontSize: '1.5rem', pb: 1 }}>{editingProduct ? 'Edit Product' : 'Add Q-Commerce Product'}</DialogTitle>
                    <DialogContent>
                        <Typography variant="body2" sx={{ color: '#94a3b8', mb: 3, fontWeight: 500 }}>
                            Fill the details to add a product in QÔÇæCommerce.
                        </Typography>
                        <Stack spacing={3}>
                            <TextField
                                fullWidth
                                label="Product Title"
                                value={newProduct.title}
                                onChange={(e) => setNewProduct({ ...newProduct, title: e.target.value })}
                                variant="outlined"
                                InputProps={{ sx: { borderRadius: 3 } }}
                            />

                            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={3}>
                                <TextField
                                    fullWidth
                                    label="Brand"
                                    value={newProduct.brand}
                                    onChange={(e) => setNewProduct({ ...newProduct, brand: e.target.value })}
                                    variant="outlined"
                                    InputProps={{ sx: { borderRadius: 3 } }}
                                />
                                <TextField
                                    fullWidth
                                    select
                                    label="Category"
                                    value={newProduct.category}
                                    onChange={(e) => setNewProduct({ ...newProduct, category: e.target.value })}
                                    variant="outlined"
                                    InputProps={{ sx: { borderRadius: 3 } }}
                                >
                                    {['Grocery', 'Snacks', 'Beverages', 'Dairy', 'Personal Care', 'Home'].map(cat => (
                                        <MenuItem key={cat} value={cat}>{cat}</MenuItem>
                                    ))}
                                </TextField>
                            </Stack>

                            <Grid container spacing={3}>
                                <Grid size={{ xs: 6 }}>
                                    <TextField
                                        fullWidth
                                        type="number"
                                        label="Price (Ôé╣)"
                                        value={newProduct.price}
                                        onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })}
                                        variant="outlined"
                                        InputProps={{ sx: { borderRadius: 3 } }}
                                    />
                                </Grid>
                                <Grid size={{ xs: 6 }}>
                                    <TextField
                                        fullWidth
                                        type="number"
                                        label="MRP (Ôé╣)"
                                        value={newProduct.mrp}
                                        onChange={(e) => setNewProduct({ ...newProduct, mrp: e.target.value })}
                                        variant="outlined"
                                        InputProps={{ sx: { borderRadius: 3 } }}
                                    />
                                </Grid>
                                <Grid size={{ xs: 6 }}>
                                    <TextField
                                        fullWidth
                                        type="number"
                                        label="Discount (%)"
                                        value={newProduct.discount}
                                        onChange={(e) => setNewProduct({ ...newProduct, discount: e.target.value })}
                                        variant="outlined"
                                        InputProps={{ sx: { borderRadius: 3 } }}
                                    />
                                </Grid>
                                <Grid size={{ xs: 6 }}>
                                    <TextField
                                        fullWidth
                                        type="number"
                                        label="Stock"
                                        value={newProduct.stock}
                                        onChange={(e) => setNewProduct({ ...newProduct, stock: e.target.value })}
                                        variant="outlined"
                                        InputProps={{ sx: { borderRadius: 3 } }}
                                    />
                                </Grid>
                            </Grid>

                            <TextField
                                fullWidth
                                label="Unit (optional)"
                                placeholder="e.g. 500g, 1L"
                                value={newProduct.unit}
                                onChange={(e) => setNewProduct({ ...newProduct, unit: e.target.value })}
                                variant="outlined"
                                InputProps={{ sx: { borderRadius: 3 } }}
                            />

                            <TextField
                                fullWidth
                                multiline
                                rows={4}
                                label="Description (optional)"
                                value={newProduct.description}
                                onChange={(e) => setNewProduct({ ...newProduct, description: e.target.value })}
                                variant="outlined"
                                InputProps={{ sx: { borderRadius: 3 } }}
                            />

                            <Box sx={{ p: 3, border: '2px dashed #f1f5f9', borderRadius: 4, bgcolor: '#f8fafc', textAlign: 'center' }}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 800, color: '#1e293b', mb: 2 }}>
                                    Product Images ({newProduct.images ? newProduct.images.split(',').filter((x: string) => x.trim()).length : 0}/3)
                                </Typography>
                                <Stack direction="row" spacing={1.5} sx={{ mb: 2.5, justifyContent: 'center' }}>
                                    {newProduct.images.split(',').map((img: string, idx: number) => {
                                        const trimmedImg = img.trim();
                                        if (!trimmedImg) return null;
                                        return (
                                            <Box key={idx} sx={{ position: 'relative', width: 70, height: 70, borderRadius: 2.5, overflow: 'hidden', border: '1.5px solid #e2e8f0' }}>
                                                <Box component="img" src={trimmedImg} sx={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                                <IconButton
                                                    size="small"
                                                    onClick={() => removeImage(trimmedImg)}
                                                    sx={{
                                                        position: 'absolute',
                                                        top: 2,
                                                        right: 2,
                                                        bgcolor: 'rgba(255,255,255,0.9)',
                                                        p: 0.5,
                                                        '&:hover': { bgcolor: 'white' }
                                                    }}
                                                >
                                                    <DeleteIcon sx={{ fontSize: 13, color: '#ef4444' }} />
                                                </IconButton>
                                            </Box>
                                        );
                                    })}
                                </Stack>
                                <Button
                                    variant="text"
                                    component="label"
                                    startIcon={isUploading ? <CircularProgress size={16} /> : <CloudUploadIcon />}
                                    disabled={isUploading || (newProduct.images ? newProduct.images.split(',').filter((x: string) => x.trim()).length >= 3 : false)}
                                    sx={{ textTransform: 'none', fontWeight: 700, borderRadius: 2, color: '#1e293b' }}
                                >
                                    {isUploading ? 'Uploading...' : 'Click to upload images'}
                                    <input type="file" hidden accept="image/*" multiple onChange={handleFileUpload} />
                                </Button>
                            </Box>
                        </Stack>
                    </DialogContent>
                    <DialogActions sx={{ p: 4 }}>
                        <Button onClick={handleCloseModal} sx={{ color: '#94a3b8', textTransform: 'none', fontWeight: 700, mr: 2 }}>Cancel</Button>
                        <Button
                            variant="contained"
                            disabled={isCreating}
                            onClick={editingProduct ? handleUpdateProduct : handleCreateProduct}
                            sx={{ bgcolor: '#1e293b', color: 'white', borderRadius: 3, textTransform: 'none', px: 5, py: 1.2, fontWeight: 800, '&:hover': { bgcolor: '#000' } }}
                        >
                            {isCreating ? <CircularProgress size={24} color="inherit" /> : (editingProduct ? 'Update Product' : 'Create Product')}
                        </Button>
                    </DialogActions>
                </Dialog>
            </Box>
        </Box>
    );
};

export default QCommerceManagement;

import { useEffect, useState } from 'react';
import {
    Box,
    Typography,
    Paper,
    Stack,
    List,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    Button,
    TextField,
    CircularProgress,
    InputAdornment,
    Grid,
    Chip,
    IconButton,
} from '@mui/material';

import DashboardIcon from '@mui/icons-material/Dashboard';
import StoreIcon from '@mui/icons-material/Store';
import WarehouseIcon from '@mui/icons-material/Warehouse';
import FlashOnIcon from '@mui/icons-material/FlashOn';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import WorkOutlineIcon from '@mui/icons-material/WorkOutline';
import ExitToAppIcon from '@mui/icons-material/ExitToApp'; 
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import { useNavigate } from 'react-router-dom';
import { ResaleService, UploadService } from '../../../services/api';
import { toast } from 'react-toastify';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import MenuItem from '@mui/material/MenuItem';

const ResaleManagement = () => {
    const navigate = useNavigate();
    const [products, setProducts] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');

    // Add/Edit Product State
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState<any>(null);
    const [isUploading, setIsUploading] = useState(false);
    const [formData, setFormData] = useState({
        title: '',
        price: '',
        condition: 'LIKE NEW',
        location: '',
        description: '',
        images: '',
        mobile: ''
    });

    useEffect(() => {
        fetchProducts();
    }, []);

    const fetchProducts = async () => {
        try {
            const { data } = await ResaleService.getAll();
            setProducts(data);
        } catch (error) {
            console.error("Failed to fetch resale products", error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        setIsUploading(true);
        try {
            const uploadPromises = Array.from(files).map(async (file) => {
                const { data } = await UploadService.uploadImagePublic(file);
                return data.url;
            });

            const uploadedUrls = await Promise.all(uploadPromises);
            setFormData(prev => {
                const existingImages = prev.images ? prev.images.split(',').map(img => img.trim()).filter(img => img !== '') : [];
                const newImages = [...existingImages, ...uploadedUrls];
                return {
                    ...prev,
                    images: newImages.join(', ')
                };
            });
            toast.success(`${uploadedUrls.length} image(s) uploaded successfully!`);
        } catch (error: any) {
            console.error("Upload failed", error);
            toast.error('Upload failed');
        } finally {
            setIsUploading(false);
        }
    };

    const removeImage = (urlToRemove: string) => {
        setFormData(prev => {
            const currentImages = prev.images.split(',').map(img => img.trim()).filter(img => img !== '');
            const filteredImages = currentImages.filter(url => url !== urlToRemove);
            return {
                ...prev,
                images: filteredImages.join(', ')
            };
        });
    };

    const handleAddProduct = async () => {
        if (!formData.title || !formData.price || !formData.condition || !formData.location || !formData.description) {
            toast.error("Please fill all required fields");
            return;
        }

        try {
            const imagesArr = formData.images.split(',').map(img => img.trim()).filter(img => img !== '');
            const payload = {
                ...formData,
                price: Number(formData.price),
                images: imagesArr,
                image: imagesArr[0] || 'https://via.placeholder.com/300',
                sellerName: 'Admin'
            };

            if (editingProduct) {
                const { data } = await ResaleService.update(editingProduct._id, payload);
                setProducts(products.map(p => p._id === editingProduct._id ? data : p));
                toast.success("Listing updated successfully!");
            } else {
                const { data } = await ResaleService.create(payload);
                setProducts([data, ...products]);
                toast.success("Resale listing created successfully!");
            }

            handleCloseModal();
        } catch (error: any) {
            console.error(error);
            toast.error(editingProduct ? "Failed to update listing" : "Failed to create listing");
        }
    };

    const handleDeleteProduct = async (id: string) => {
        if (window.confirm("Delete this listing?")) {
            try {
                await ResaleService.delete(id);
                setProducts(products.filter(p => p._id !== id));
                toast.success("Listing deleted successfully");
            } catch (error) {
                toast.error("Failed to delete listing");
            }
        }
    };

    const handleEditProduct = (product: any) => {
        setEditingProduct(product);
        setFormData({
            title: product.title || '',
            price: product.price?.toString() || '',
            condition: product.condition || 'LIKE NEW',
            location: product.location || '',
            description: product.description || '',
            images: Array.isArray(product.images) ? product.images.join(', ') : '',
            mobile: product.mobile || ''
        });
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingProduct(null);
        setFormData({
            title: '',
            price: '',
            condition: 'LIKE NEW',
            location: '',
            description: '',
            images: '',
            mobile: ''
        });
    };

    const menuItems = [
        { name: 'Overview', icon: <DashboardIcon sx={{ fontSize: 20 }} />, path: '/admin/dashboard' },
        { name: 'Retail', icon: <StoreIcon sx={{ fontSize: 20 }} />, path: '/admin/retail' },
        { name: 'Wholesale', icon: <WarehouseIcon sx={{ fontSize: 20 }} />, path: '/admin/wholesale' },
        { name: 'Q-Commerce', icon: <FlashOnIcon sx={{ fontSize: 20 }} />, path: '/admin/quick' },
        { name: 'Resale', icon: <AutorenewIcon sx={{ fontSize: 20 }} />, path: '/admin/resale', active: true },
        { name: 'Freelance', icon: <WorkOutlineIcon sx={{ fontSize: 20 }} />, path: '/admin/freelance' },
    ];

    return (
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'white' }}>
            {/* Sidebar */}
            <Box sx={{ width: 260, bgcolor: 'white', borderRight: '1px solid #f1f5f9', p: 3, display: 'flex', flexDirection: 'column', height: '100vh', position: 'sticky', top: 0 }}>
                <Stack direction="row" alignItems="center" spacing={1.5} sx={{ mb: 5, px: 1 }}>
                    <Box sx={{ bgcolor: 'black', p: 0.8, borderRadius: 1.5, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Box component="span" sx={{ color: 'white', fontWeight: 900, fontSize: '1.2rem', lineHeight: 1 }}>R</Box>
                    </Box>
                    <Typography variant="h6" sx={{ fontWeight: 800, fontSize: '1.25rem', color: '#1e293b' }}>retails</Typography>
                </Stack>

                <List disablePadding sx={{ flexGrow: 1 }}>
                    {menuItems.map((item) => (
                        <ListItemButton
                            key={item.name}
                            onClick={() => !item.active && navigate(item.path)}
                            sx={{
                                mb: 1,
                                borderRadius: 3,
                                bgcolor: item.active ? '#CFE8EC' : 'transparent',
                                color: item.active ? '#1e293b' : '#64748b',
                                '&:hover': { bgcolor: item.active ? '#CFE8EC' : '#f8fafc' },
                                py: 1.2,
                                px: 2
                            }}
                        >
                            <ListItemIcon sx={{ minWidth: 35, color: item.active ? '#1e293b' : '#64748b' }}>
                                {item.icon}
                            </ListItemIcon>
                            <ListItemText
                                primary={item.name}
                                primaryTypographyProps={{ fontWeight: item.active ? 700 : 500, fontSize: '0.95rem' }}
                            />
                        </ListItemButton>
                    ))}
                </List>

                <Box sx={{ mt: 'auto', pt: 2 }}>

                    <Stack onClick={() => { localStorage.removeItem('token'); localStorage.removeItem('userRole'); navigate('/admin/login'); }} direction="row" alignItems="center" spacing={2} sx={{ px: 2, cursor: 'pointer', color: '#ef4444' }}>
                        <ExitToAppIcon sx={{ fontSize: 20 }} />
                        <Typography variant="body2" fontWeight={600}>Leave</Typography>
                    </Stack>
                </Box>
            </Box>

            {/* Main Content */}
            <Box sx={{ flexGrow: 1, p: 4, bgcolor: '#f8fafc', overflow: 'auto' }}>
                {/* Header */}
                <Stack direction="row" justifyContent="space-between" alignItems="flex-start" sx={{ mb: 4 }}>
                    <Box>
                        <Typography variant="h4" sx={{ fontWeight: 800, color: '#1e293b', mb: 0.5 }}>Resale Management</Typography>
                        <Typography variant="body2" sx={{ color: '#64748b', fontWeight: 500 }}>Track and manage your community resale marketplace.</Typography>
                    </Box>
                    <Stack direction="row" spacing={2}>

                        <Button
                            variant="contained"
                            onClick={() => setIsModalOpen(true)}
                            startIcon={<AddIcon />}
                            sx={{
                                bgcolor: '#CFE8EC',
                                color: '#1e293b',
                                borderRadius: 3,
                                px: 3,
                                fontWeight: 700,
                                textTransform: 'none',
                                boxShadow: 'none',
                                '&:hover': { bgcolor: '#b8dbe2', boxShadow: 'none' }
                            }}
                        >
                            Add Listing
                        </Button>
                    </Stack>
                </Stack>

                {/* Recently Listed Items */}
                <Box sx={{ mb: 6 }}>
                    <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 3 }}>
                        <Stack direction="row" alignItems="center" spacing={2}>
                            <Typography variant="h6" sx={{ fontWeight: 800, color: '#1e293b' }}>Recently Listed Items</Typography>
                            <Chip label={`${products.length} Items`} size="small" sx={{ bgcolor: '#f1f5f9', fontWeight: 800, color: '#64748b' }} />
                        </Stack>
                        <Button onClick={fetchProducts} variant="text" sx={{ color: '#64748b', fontWeight: 700, cursor: 'pointer', textTransform: 'none' }}>Refresh</Button>
                    </Stack>

                    <Grid container spacing={3}>
                        {products.map((item, i) => (
                            <Grid key={item._id || i} size={{ xs: 12, md: 4 }}>
                                <Paper elevation={0} sx={{ p: 2, borderRadius: 5, bgcolor: 'white', border: '1px solid #f1f5f9' }}>
                                    <Stack direction="row" spacing={2}>
                                        <Box sx={{ width: 100, height: 100, borderRadius: 4, overflow: 'hidden', bgcolor: '#f8fafc' }}>
                                            <Box component="img" src={item.images?.[0] || 'https://via.placeholder.com/150'} sx={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                        </Box>
                                        <Box sx={{ flexGrow: 1 }}>
                                            <Stack direction="row" justifyContent="space-between" alignItems="flex-start" sx={{ mb: 0.5 }}>
                                                <Typography variant="subtitle1" sx={{ fontWeight: 800, color: '#1e293b' }}>{item.title}</Typography>
                                                <Stack direction="row" spacing={1}>
                                                    <IconButton size="small" onClick={() => handleEditProduct(item)} sx={{ color: '#94a3b8' }}><EditIcon sx={{ fontSize: 16 }} /></IconButton>
                                                    <IconButton size="small" onClick={() => handleDeleteProduct(item._id)} sx={{ color: '#ef4444' }}><DeleteIcon sx={{ fontSize: 16 }} /></IconButton>
                                                </Stack>
                                            </Stack>
                                            <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
                                                <Chip label={item.condition || 'Used'} size="small" sx={{ height: 18, fontSize: '0.6rem', fontWeight: 900, bgcolor: '#f1f5f9' }} />
                                                <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700 }}>{item.location}</Typography>
                                            </Stack>
                                            <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700, display: 'block', mb: 1 }}>{item.description ? item.description.substring(0, 30) + '...' : 'No description'}</Typography>
                                            <Stack direction="row" alignItems="baseline" spacing={1}>
                                                <Typography variant="h6" sx={{ fontWeight: 900, color: '#1e293b' }}>Ôé╣{item.price}</Typography>
                                            </Stack>
                                        </Box>
                                    </Stack>
                                </Paper>
                            </Grid>
                        ))}
                        {products.length === 0 && !isLoading && <Typography sx={{ p: 2, color: '#94a3b8' }}>No resale items found.</Typography>}
                    </Grid>
                </Box>

                {/* Loading Indicator */}
                {isLoading && products.length === 0 && (
                    <Box sx={{ display: 'flex', justifyContent: 'center', p: 5 }}><CircularProgress sx={{ color: '#CFE8EC' }} /></Box>
                )}
            </Box>

            {/* Add Product Modal */}
            <Dialog open={isModalOpen} onClose={handleCloseModal} maxWidth="sm" fullWidth PaperProps={{ sx: { borderRadius: 4 } }}>
                <DialogTitle sx={{ fontWeight: 800, px: 3, pt: 3 }}>{editingProduct ? 'Edit Resale Listing' : 'Add New Resale Listing'}</DialogTitle>
                <DialogContent sx={{ px: 3 }}>
                    <Stack spacing={2.5} sx={{ py: 2 }}>
                        <TextField fullWidth label="Title" variant="outlined" value={formData.title} onChange={(e) => setFormData({ ...formData, title: e.target.value })} sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }} />

                        <Stack direction="row" spacing={2}>
                            <TextField fullWidth type="number" label="Price (Ôé╣)" value={formData.price} onChange={(e) => setFormData({ ...formData, price: e.target.value })} sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }} />
                            <TextField fullWidth select label="Condition" value={formData.condition} onChange={(e) => setFormData({ ...formData, condition: e.target.value })} sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }}>
                                {['NEW', 'LIKE NEW', 'GOOD', 'FAIR'].map(cond => <MenuItem key={cond} value={cond}>{cond}</MenuItem>)}
                            </TextField>
                        </Stack>

                        <Stack direction="row" spacing={2}>
                            <TextField fullWidth label="Location" placeholder="e.g. San Francisco, CA" value={formData.location} onChange={(e) => setFormData({ ...formData, location: e.target.value })} sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }} />
                            <TextField fullWidth label="Contact Mobile" value={formData.mobile} onChange={(e) => setFormData({ ...formData, mobile: e.target.value })} sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }} />
                        </Stack>
                        <TextField fullWidth multiline rows={3} label="Description" value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} sx={{ '& .MuiOutlinedInput-root': { borderRadius: 2 } }} />

                        <Box sx={{ mt: 1 }}>
                            <Typography variant="caption" sx={{ fontWeight: 700, color: '#64748b', mb: 1, display: 'block' }}>
                                PRODUCT IMAGES ({formData.images ? formData.images.split(',').length : 0}/3)
                            </Typography>
                            <Stack direction="row" spacing={2} sx={{ mb: 2, flexWrap: 'wrap', gap: 1 }}>
                                {formData.images.split(',').map((img, idx) => {
                                    const trimmedImg = img.trim();
                                    if (!trimmedImg) return null;
                                    return (
                                        <Box key={idx} sx={{ position: 'relative', width: 80, height: 80, borderRadius: 2, overflow: 'hidden', border: '1px solid #e2e8f0' }}>
                                            <Box component="img" src={trimmedImg} sx={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                            <IconButton
                                                size="small"
                                                onClick={() => removeImage(trimmedImg)}
                                                sx={{ position: 'absolute', top: 2, right: 2, bgcolor: 'rgba(255,255,255,0.8)', '&:hover': { bgcolor: 'white' }, p: 0.5 }}
                                            >
                                                <DeleteIcon sx={{ fontSize: 14, color: '#ef4444' }} />
                                            </IconButton>
                                        </Box>
                                    );
                                })}
                            </Stack>
                            <Button
                                variant="outlined"
                                component="label"
                                fullWidth
                                startIcon={isUploading ? <CircularProgress size={20} /> : <CloudUploadIcon />}
                                disabled={isUploading || (formData.images ? formData.images.split(',').length >= 3 : false)}
                                sx={{ borderRadius: 2, textTransform: 'none', py: 1.5, borderStyle: 'dashed', borderWidth: 2 }}
                            >
                                {isUploading ? 'Uploading...' : 'Upload Images (Max 3)'}
                                <input type="file" hidden accept="image/*" multiple onChange={handleFileUpload} />
                            </Button>
                        </Box>
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3, pt: 1 }}>
                    <Button onClick={handleCloseModal} sx={{ color: '#64748b', fontWeight: 600 }}>Cancel</Button>
                    <Button variant="contained" onClick={handleAddProduct} sx={{ bgcolor: 'black', color: 'white', borderRadius: 3, px: 4, fontWeight: 700, '&:hover': { bgcolor: '#1e293b' } }}>{editingProduct ? 'Update Listing' : 'Confirm Entry'}</Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default ResaleManagement;

import { useEffect, useState } from 'react';
import { Box, Typography, Paper, Stack, IconButton, List, ListItemButton, ListItemIcon, ListItemText, Grid, Chip, TextField, CircularProgress, Button, Dialog, DialogTitle, DialogContent, DialogActions, MenuItem } from '@mui/material';
import { toast } from 'react-toastify';
import DashboardIcon from '@mui/icons-material/Dashboard';
import StoreIcon from '@mui/icons-material/Store';
import WarehouseIcon from '@mui/icons-material/Warehouse';
import FlashOnIcon from '@mui/icons-material/FlashOn';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import WorkOutlineIcon from '@mui/icons-material/WorkOutline';
import ExitToAppIcon from '@mui/icons-material/ExitToApp';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import InventoryIcon from '@mui/icons-material/Inventory';
import HeadsetIcon from '@mui/icons-material/Headset';
import ChairIcon from '@mui/icons-material/Chair';
import KeyboardIcon from '@mui/icons-material/Keyboard';
import LaptopIcon from '@mui/icons-material/Laptop';
import MonitorIcon from '@mui/icons-material/Monitor';
import { useNavigate } from 'react-router-dom';
import { OrderService, ProductService, UploadService } from '../../../services/api';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';

const RetailManagement = () => {
    const navigate = useNavigate();
    const [orders, setOrders] = useState<any[]>([]);
    const [products, setProducts] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchTerm] = useState('');
    const [view, setView] = useState<'orders' | 'products'>('orders');

    // Add Product Modal State
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState<any>(null);
    const [newProduct, setNewProduct] = useState({
        title: '', price: '', category: '', brand: '', stock: '', description: '', images: ''
    });
    const [isUploading, setIsUploading] = useState(false);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [ordersRes, productsRes] = await Promise.all([
                OrderService.getAll(),
                ProductService.getAll()
            ]);
            setOrders(ordersRes.data);
            setProducts(productsRes.data.products || productsRes.data);
        } catch (error) {
            console.error("Failed to fetch retail data", error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        setIsUploading(true);
        try {
            const uploadPromises = Array.from(files).map(async (file) => {
                const { data } = await UploadService.uploadImage(file);
                return data.url;
            });

            const uploadedUrls = await Promise.all(uploadPromises);
            setNewProduct(prev => {
                const existingImages = prev.images ? prev.images.split(',').map((img: string) => img.trim()).filter((img: string) => img !== '') : [];
                const newImages = [...existingImages, ...uploadedUrls];
                return {
                    ...prev,
                    images: newImages.join(', ')
                };
            });
            toast.success(`${uploadedUrls.length} image(s) uploaded successfully!`);
        } catch (error: any) {
            console.error("Upload failed detailed:", error.response?.data || error.message);
            toast.error(`Upload failed: ${error.response?.data?.message || error.message}`);
        } finally {
            setIsUploading(false);
        }
    };

    const removeImage = (urlToRemove: string) => {
        setNewProduct(prev => {
            const currentImages = prev.images.split(',').map((img: string) => img.trim()).filter((img: string) => img !== '');
            const filteredImages = currentImages.filter((url: string) => url !== urlToRemove);
            return {
                ...prev,
                images: filteredImages.join(', ')
            };
        });
    };

    const handleAddProduct = async () => {
        // Validate required fields
        if (!newProduct.title.trim()) {
            toast.error('Product name is required');
            return;
        }
        if (!newProduct.brand.trim()) {
            toast.error('Brand is required');
            return;
        }
        if (!newProduct.category.trim()) {
            toast.error('Category is required');
            return;
        }
        if (!newProduct.price || Number(newProduct.price) <= 0) {
            toast.error('Valid price is required');
            return;
        }
        if (!newProduct.stock || Number(newProduct.stock) < 0) {
            toast.error('Valid stock count is required');
            return;
        }

        try {
            const images = newProduct.images.split(',').map((img: string) => img.trim()).filter((img: string) => img !== '');

            const productData = {
                title: newProduct.title.trim(),
                price: Number(newProduct.price),
                stock: Number(newProduct.stock),
                category: newProduct.category.trim(),
                brand: newProduct.brand.trim(),
                description: newProduct.description.trim() || undefined,
                images,
                image: images[0] || 'https://via.placeholder.com/600'
            };

            console.log('Creating retail product with payload:', productData);

            const { data } = await ProductService.create(productData);
            setProducts([data, ...products]);
            setIsModalOpen(false);
            setNewProduct({ title: '', price: '', category: '', brand: '', stock: '', description: '', images: '' });
            toast.success("Product created successfully!");
        } catch (error: any) {
            console.error("Failed to create product:", error.response?.data || error.message);
            toast.error(`Failed to create product: ${error.response?.data?.message || error.message}`);
        }
    };

    const handleDeleteProduct = async (id: string) => {
        if (window.confirm("Delete this retail product?")) {
            try {
                await ProductService.delete(id);
                setProducts(products.filter((p: any) => p._id !== id));
                toast.success("Product deleted successfully");
            } catch (error) {
                toast.error("Failed to delete product");
            }
        }
    };

    const handleEditProduct = (product: any) => {
        setEditingProduct(product);
        setNewProduct({
            title: product.title || '',
            price: product.price?.toString() || '',
            category: product.category || '',
            brand: product.brand || '',
            stock: product.stock?.toString() || '',
            description: product.description || '',
            images: Array.isArray(product.images) ? product.images.join(', ') : ''
        });
        setIsModalOpen(true);
    };

    const handleUpdateProduct = async () => {
        if (!editingProduct) return;

        // Validate required fields
        if (!newProduct.title.trim()) {
            toast.error('Product name is required');
            return;
        }
        if (!newProduct.brand.trim()) {
            toast.error('Brand is required');
            return;
        }
        if (!newProduct.category.trim()) {
            toast.error('Category is required');
            return;
        }
        if (!newProduct.price || Number(newProduct.price) <= 0) {
            toast.error('Valid price is required');
            return;
        }
        if (!newProduct.stock || Number(newProduct.stock) < 0) {
            toast.error('Valid stock count is required');
            return;
        }

        try {
            const images = newProduct.images.split(',').map((img: string) => img.trim()).filter((img: string) => img !== '');

            const productData = {
                title: newProduct.title.trim(),
                price: Number(newProduct.price),
                stock: Number(newProduct.stock),
                category: newProduct.category.trim(),
                brand: newProduct.brand.trim(),
                description: newProduct.description.trim() || undefined,
                images,
                image: images[0] || 'https://via.placeholder.com/600'
            };

            console.log('Updating product with payload:', productData);

            const { data } = await ProductService.update(editingProduct._id, productData);
            setProducts(products.map((p: any) => p._id === editingProduct._id ? data : p));
            setIsModalOpen(false);
            setEditingProduct(null);
            setNewProduct({ title: '', price: '', category: '', brand: '', stock: '', description: '', images: '' });
            toast.success("Product updated successfully!");
        } catch (error: any) {
            console.error("Failed to update product:", error.response?.data || error.message);
            toast.error(`Failed to update product: ${error.response?.data?.message || error.message}`);
        }
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingProduct(null);
        setNewProduct({ title: '', price: '', category: '', brand: '', stock: '', description: '', images: '' });
    };

    const menuItems = [
        { name: 'Overview', icon: <DashboardIcon sx={{ fontSize: 20 }} />, path: '/admin/dashboard' },
        { name: 'Retail', icon: <StoreIcon sx={{ fontSize: 20 }} />, path: '/admin/retail', active: true },
        { name: 'Wholesale', icon: <WarehouseIcon sx={{ fontSize: 20 }} />, path: '/admin/wholesale' },
        { name: 'Q-Commerce', icon: <FlashOnIcon sx={{ fontSize: 20 }} />, path: '/admin/quick' },
        { name: 'Resale', icon: <AutorenewIcon sx={{ fontSize: 20 }} />, path: '/admin/resale' },
        { name: 'Freelance', icon: <WorkOutlineIcon sx={{ fontSize: 20 }} />, path: '/admin/freelance' },
    ];

    const filteredOrders = (orders || []).filter((order: any) =>
        order._id?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        order.user?.username?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const filteredProducts = (products || []).filter((product: any) =>
        product.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        product.brand?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const pendingOrders = filteredOrders.filter((o: any) => !o.isPaid);
    const completedOrders = filteredOrders.filter((o: any) => o.isPaid);

    // Helper to get random tech icon for demo feel
    const getOrderIcon = (index: number) => {
        const icons = [<HeadsetIcon />, <ChairIcon />, <KeyboardIcon />, <LaptopIcon />, <MonitorIcon />];
        return icons[index % icons.length];
    };

    return (
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'white' }}>
            {/* Sidebar */}
            <Box sx={{ width: 260, bgcolor: 'white', borderRight: '1px solid #f1f5f9', p: 3, display: 'flex', flexDirection: 'column', height: '100vh', position: 'sticky', top: 0 }}>
                {/* Logo Area */}
                <Stack direction="row" alignItems="center" spacing={1.5} sx={{ mb: 6, px: 2 }}>
                    <Box sx={{ bgcolor: '#f1f5f9', p: 1, borderRadius: 2, display: 'flex' }}>
                        <InventoryIcon sx={{ color: '#1e293b', fontSize: 20 }} />
                    </Box>
                    <Typography variant="h6" sx={{ fontWeight: 800, color: '#1e293b' }}>retails</Typography>
                </Stack>

                <List disablePadding>
                    {menuItems.map((item) => (
                        <ListItemButton
                            key={item.name}
                            onClick={() => item.path !== '/admin/retail' && navigate(item.path)}
                            sx={{
                                mb: 1,
                                borderRadius: 3,
                                bgcolor: item.active ? '#CFE8EC' : 'transparent',
                                color: item.active ? '#1e293b' : '#64748b',
                                '&:hover': { bgcolor: item.active ? '#CFE8EC' : '#f8fafc', color: item.active ? '#1e293b' : '#314155' },
                                py: 1.2,
                                px: 2
                            }}
                        >
                            <ListItemIcon sx={{ minWidth: 35, color: item.active ? '#1e293b' : '#64748b' }}>
                                {item.icon}
                            </ListItemIcon>
                            <ListItemText
                                primary={item.name}
                                primaryTypographyProps={{ fontWeight: item.active ? 700 : 500, fontSize: '0.9rem' }}
                            />
                        </ListItemButton>
                    ))}
                </List>

                <Box sx={{ mt: 'auto', borderTop: '1px solid #f1f5f9', pt: 3 }}>
                    <Stack onClick={() => { localStorage.removeItem('token'); localStorage.removeItem('userRole'); navigate('/admin/login'); }} direction="row" alignItems="center" spacing={2} sx={{ px: 2, cursor: 'pointer', color: '#ef4444', '&:hover': { color: '#b91c1c' } }}>
                        <ExitToAppIcon sx={{ fontSize: 20 }} />
                        <Typography variant="body2" fontWeight={600}>Leave</Typography>
                    </Stack>
                </Box>
            </Box>

            {/* Main Content */}
            <Box sx={{ flexGrow: 1, p: 4, overflow: 'auto', bgcolor: '#f8fafc' }}>
                <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 6 }}>
                    <Box>
                        <Typography variant="h3" sx={{ fontWeight: 800, color: '#1e293b', letterSpacing: '-0.5px' }}>Retail Management</Typography>
                        <Typography variant="body1" sx={{ color: '#94a3b8', fontWeight: 500, mt: 0.5 }}>Track and manage your retail ecosystem</Typography>
                    </Box>
                    <Button
                        variant="contained"
                        onClick={() => setIsModalOpen(true)}
                        startIcon={<AddIcon />}
                        sx={{
                            bgcolor: '#CFE8EC',
                            color: '#1e293b',
                            borderRadius: 2.5,
                            fontWeight: 700,
                            textTransform: 'none',
                            px: 3.5,
                            py: 1.2,
                            boxShadow: 'none',
                            fontSize: '0.95rem',
                            '&:hover': { bgcolor: '#bde0e5', boxShadow: 'none' }
                        }}
                    >
                        Create Product
                    </Button>
                </Stack>

                {/* Subtle View Switcher */}
                <Stack direction="row" spacing={3} sx={{ mb: 4, px: 1 }}>
                    <Typography
                        onClick={() => setView('orders')}
                        sx={{
                            cursor: 'pointer',
                            fontWeight: 800,
                            color: view === 'orders' ? '#1e293b' : '#94a3b8',
                            fontSize: '1rem',
                            borderBottom: view === 'orders' ? '2.5px solid #1e293b' : 'none',
                            pb: 0.5,
                            transition: '0.2s'
                        }}
                    >
                        Order History
                    </Typography>
                    <Typography
                        onClick={() => setView('products')}
                        sx={{
                            cursor: 'pointer',
                            fontWeight: 800,
                            color: view === 'products' ? '#1e293b' : '#94a3b8',
                            fontSize: '1rem',
                            borderBottom: view === 'products' ? '2.5px solid #1e293b' : 'none',
                            pb: 0.5,
                            transition: '0.2s'
                        }}
                    >
                        Products
                    </Typography>
                </Stack>

                {isLoading ? (
                    <Box sx={{ display: 'flex', justifyContent: 'center', p: 8 }}>
                        <CircularProgress sx={{ color: '#1e293b' }} />
                    </Box>
                ) : view === 'orders' ? (
                    <>
                        {/* Pending Orders */}
                        <Box sx={{ mb: 6 }}>
                            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 3, px: 1 }}>
                                <Stack direction="row" alignItems="center" spacing={1.5}>
                                    <Typography variant="h6" sx={{ fontWeight: 800, color: '#1e293b' }}>Order List</Typography>
                                    <Box sx={{ bgcolor: '#f1f5f9', px: 1.5, py: 0.4, borderRadius: 2 }}>
                                        <Typography variant="caption" sx={{ color: '#1e293b', fontWeight: 800 }}>{pendingOrders.length} Pending</Typography>
                                    </Box>
                                </Stack>
                                <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 700, cursor: 'pointer', '&:hover': { color: '#1e293b' } }}>View all</Typography>
                            </Stack>

                            <Stack spacing={1.8}>
                                {pendingOrders.map((order: any, idx: number) => (
                                    <Paper
                                        key={order._id}
                                        elevation={0}
                                        sx={{
                                            p: 3,
                                            borderRadius: 5,
                                            bgcolor: 'white',
                                            border: '1.5px solid #f8fafc',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'space-between',
                                            transition: '0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                            '&:hover': { boxShadow: '0 10px 25px rgba(0,0,0,0.02)', borderColor: '#f1f5f9' }
                                        }}
                                    >
                                        <Stack direction="row" alignItems="center" spacing={3}>
                                            <Box sx={{ width: 48, height: 48, bgcolor: '#f8fafc', borderRadius: 2.5, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                <Box sx={{ color: '#94a3b8' }}>{getOrderIcon(idx)}</Box>
                                            </Box>
                                            <Box>
                                                <Typography variant="subtitle1" sx={{ fontWeight: 800, color: '#1e293b', mb: 0.2 }}>Order from {order.user?.username || 'Guest'}</Typography>
                                                <Typography variant="body2" sx={{ color: '#94a3b8', fontWeight: 600 }}>Order #ORD-{order._id?.substring(order._id?.length - 4).toUpperCase()}</Typography>
                                            </Box>
                                        </Stack>
                                        <Stack direction="row" alignItems="center" spacing={5}>
                                            <Typography variant="h6" sx={{ fontWeight: 900, color: '#1e293b' }}>Ôé╣{order.totalPrice}</Typography>
                                            <Chip
                                                label="PENDING"
                                                sx={{
                                                    bgcolor: '#CFE8EC',
                                                    color: '#1e293b',
                                                    fontWeight: 900,
                                                    fontSize: '0.65rem',
                                                    height: 26,
                                                    borderRadius: 2,
                                                    px: 1
                                                }}
                                            />
                                            <IconButton size="small"><MoreVertIcon sx={{ color: '#cbd5e1' }} /></IconButton>
                                        </Stack>
                                    </Paper>
                                ))}
                                {pendingOrders.length === 0 && <Typography variant="body2" sx={{ color: '#94a3b8', textAlign: 'center', py: 5 }}>No pending orders.</Typography>}
                            </Stack>
                        </Box>

                        {/* Completed Orders */}
                        <Box>
                            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 3, px: 1 }}>
                                <Stack direction="row" alignItems="center" spacing={1.5}>
                                    <Typography variant="h6" sx={{ fontWeight: 800, color: '#1e293b' }}>Completed Orders</Typography>
                                    <Box sx={{ bgcolor: '#f1f5f9', px: 1.5, py: 0.4, borderRadius: 2 }}>
                                        <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 800 }}>{completedOrders.length} Total</Typography>
                                    </Box>
                                </Stack>
                            </Stack>

                            <Stack spacing={1.8}>
                                {completedOrders.map((order: any, idx: number) => (
                                    <Paper
                                        key={order._id}
                                        elevation={0}
                                        sx={{
                                            p: 3,
                                            borderRadius: 5,
                                            bgcolor: 'white',
                                            border: '1.5px solid #f8fafc',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'space-between'
                                        }}
                                    >
                                        <Stack direction="row" alignItems="center" spacing={3}>
                                            <Box sx={{ width: 48, height: 48, bgcolor: '#f8fafc', borderRadius: 2.5, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                <Box sx={{ color: '#cbd5e1' }}>{getOrderIcon(idx + 10)}</Box>
                                            </Box>
                                            <Box>
                                                <Typography variant="subtitle1" sx={{ fontWeight: 800, color: '#1e293b', mb: 0.2 }}>Order from {order.user?.username || 'Guest'}</Typography>
                                                <Typography variant="body2" sx={{ color: '#94a3b8', fontWeight: 600 }}>Order #ORD-{order._id?.substring(order._id?.length - 4).toUpperCase()}</Typography>
                                            </Box>
                                        </Stack>
                                        <Stack direction="row" alignItems="center" spacing={5}>
                                            <Typography variant="h6" sx={{ fontWeight: 900, color: '#1e293b' }}>Ôé╣{order.totalPrice}</Typography>
                                            <Chip
                                                label="COMPLETED"
                                                sx={{
                                                    bgcolor: '#f1f5f9',
                                                    color: '#94a3b8',
                                                    fontWeight: 900,
                                                    fontSize: '0.65rem',
                                                    height: 26,
                                                    borderRadius: 2,
                                                    px: 1
                                                }}
                                            />
                                            <IconButton size="small"><MoreVertIcon sx={{ color: '#cbd5e1' }} /></IconButton>
                                        </Stack>
                                    </Paper>
                                ))}
                                {completedOrders.length === 0 && <Typography variant="body2" sx={{ color: '#94a3b8', textAlign: 'center', py: 5 }}>No completed orders found.</Typography>}
                            </Stack>
                        </Box>
                    </>
                ) : (
                    <Box>
                        <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 4, px: 1 }}>
                            <Typography variant="h6" sx={{ fontWeight: 800, color: '#1e293b' }}>Product Inventory</Typography>
                        </Stack>
                        <Grid container spacing={3.5}>
                            {filteredProducts.map((product: any) => (
                                <Grid key={product._id} size={{ xs: 12, sm: 6, md: 4, lg: 3 }}>
                                    <Paper
                                        elevation={0}
                                        sx={{
                                            p: 2.5,
                                            borderRadius: 5,
                                            border: '1.5px solid #f8fafc',
                                            height: '100%',
                                            display: 'flex',
                                            flexDirection: 'column',
                                            bgcolor: 'white',
                                            transition: '0.3s',
                                            '&:hover': { boxShadow: '0 12px 30px rgba(0,0,0,0.03)', transform: 'translateY(-4px)' }
                                        }}
                                    >
                                        <Box sx={{ position: 'relative', width: '100%', height: 180, mb: 2.5 }}>
                                            <Box component="img" src={product.images?.[0]} sx={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 4, bgcolor: '#f8fafc' }} />
                                            <Chip
                                                label={product.stock > 0 ? "In Stock" : "Out of Stock"}
                                                size="small"
                                                sx={{
                                                    position: 'absolute',
                                                    top: 12,
                                                    right: 12,
                                                    bgcolor: product.stock > 0 ? 'rgba(255,255,255,0.9)' : '#fee2e2',
                                                    color: product.stock > 0 ? '#1e293b' : '#ef4444',
                                                    fontWeight: 800,
                                                    backdropFilter: 'blur(4px)'
                                                }}
                                            />
                                        </Box>
                                        <Typography variant="subtitle1" sx={{ fontWeight: 800, color: '#1e293b', mb: 0.5 }}>{product.title}</Typography>
                                        <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.5px' }}>{product.brand || 'No Brand'}</Typography>
                                        <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mt: 'auto', pt: 3 }}>
                                            <Typography variant="h6" sx={{ fontWeight: 900, color: '#1e293b' }}>Ôé╣{product.price}</Typography>
                                            <Stack direction="row" spacing={0.5}>
                                                <IconButton size="small" onClick={() => handleEditProduct(product)} sx={{ color: '#94a3b8', '&:hover': { color: '#1e293b', bgcolor: '#f1f5f9' } }}><EditIcon fontSize="small" /></IconButton>
                                                <IconButton size="small" sx={{ color: '#fee2e2', '&:hover': { color: '#ef4444', bgcolor: '#fef2f2' } }} onClick={() => handleDeleteProduct(product._id)}><DeleteIcon fontSize="small" /></IconButton>
                                            </Stack>
                                        </Stack>
                                    </Paper>
                                </Grid>
                            ))}
                            {filteredProducts.length === 0 && <Grid size={{ xs: 12 }}><Typography variant="body1" sx={{ color: '#94a3b8', textAlign: 'center', py: 10 }}>No products found in inventory.</Typography></Grid>}
                        </Grid>
                    </Box>
                )}

                {/* Add Product Modal */}
                <Dialog
                    open={isModalOpen}
                    onClose={handleCloseModal}
                    maxWidth="sm"
                    fullWidth
                    PaperProps={{ sx: { borderRadius: 6, p: 1 } }}
                >
                    <DialogTitle sx={{ fontWeight: 900, fontSize: '1.5rem', pb: 1 }}>{editingProduct ? 'Edit Product' : 'List a New Product'}</DialogTitle>
                    <DialogContent>
                        <Typography variant="body2" sx={{ color: '#94a3b8', mb: 3, fontWeight: 500 }}>All fields are required to list a product in the marketplace.</Typography>
                        <Stack spacing={3}>
                            <TextField fullWidth label="Product Name" placeholder="e.g. Wireless Noise Canceling Headphones" value={newProduct.title} onChange={(e) => setNewProduct({ ...newProduct, title: e.target.value })} variant="outlined" InputProps={{ sx: { borderRadius: 3 } }} />
                            <Grid container spacing={3}>
                                <Grid size={{ xs: 6 }}>
                                    <TextField fullWidth type="number" label="Price (Ôé╣)" value={newProduct.price} onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })} variant="outlined" InputProps={{ sx: { borderRadius: 3 } }} />
                                </Grid>
                                <Grid size={{ xs: 6 }}>
                                    <TextField fullWidth type="number" label="Stock Count" value={newProduct.stock} onChange={(e) => setNewProduct({ ...newProduct, stock: e.target.value })} variant="outlined" InputProps={{ sx: { borderRadius: 3 } }} />
                                </Grid>
                            </Grid>
                            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={3}>
                                <TextField fullWidth select label="Category" value={newProduct.category} onChange={(e) => setNewProduct({ ...newProduct, category: e.target.value })} variant="outlined" InputProps={{ sx: { borderRadius: 3 } }}>
                                    {['Electronics', 'Fashion', 'Home', 'Beauty', 'Sports'].map(cat => <MenuItem key={cat} value={cat}>{cat}</MenuItem>)}
                                </TextField>
                                <TextField fullWidth label="Brand" placeholder="e.g. Sony" value={newProduct.brand} onChange={(e) => setNewProduct({ ...newProduct, brand: e.target.value })} variant="outlined" InputProps={{ sx: { borderRadius: 3 } }} />
                            </Stack>
                            <TextField fullWidth multiline rows={4} label="Product Description" value={newProduct.description} onChange={(e) => setNewProduct({ ...newProduct, description: e.target.value })} variant="outlined" InputProps={{ sx: { borderRadius: 3 } }} />

                            <Box sx={{ p: 3, border: '2px dashed #f1f5f9', borderRadius: 4, bgcolor: '#f8fafc', textAlign: 'center' }}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 800, color: '#1e293b', mb: 2 }}>Product Images ({newProduct.images.split(',').filter((x: string) => x.trim()).length}/3)</Typography>
                                <Stack direction="row" spacing={1.5} sx={{ mb: 2.5, justifyContent: 'center' }}>
                                    {newProduct.images.split(',').map((img: string, idx: number) => {
                                        const trimmedImg = img.trim();
                                        if (!trimmedImg) return null;
                                        return (
                                            <Box key={idx} sx={{ position: 'relative', width: 70, height: 70, borderRadius: 2.5, overflow: 'hidden', border: '1.5px solid #e2e8f0' }}>
                                                <Box component="img" src={trimmedImg} sx={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                                <IconButton size="small" onClick={() => removeImage(trimmedImg)} sx={{ position: 'absolute', top: 2, right: 2, bgcolor: 'rgba(255,255,255,0.9)', p: 0.5, '&:hover': { bgcolor: 'white' } }}>
                                                    <DeleteIcon sx={{ fontSize: 13, color: '#ef4444' }} />
                                                </IconButton>
                                            </Box>
                                        );
                                    })}
                                </Stack>
                                <Button
                                    variant="text"
                                    component="label"
                                    startIcon={isUploading ? <CircularProgress size={16} /> : <CloudUploadIcon />}
                                    disabled={isUploading || (newProduct.images ? newProduct.images.split(',').length >= 3 : false)}
                                    sx={{ textTransform: 'none', fontWeight: 700, borderRadius: 2, color: '#1e293b' }}
                                >
                                    {isUploading ? 'Uploading...' : 'Click to upload images'}
                                    <input type="file" hidden accept="image/*" multiple onChange={handleFileUpload} />
                                </Button>
                            </Box>
                        </Stack>
                    </DialogContent>
                    <DialogActions sx={{ p: 4 }}>
                        <Button onClick={handleCloseModal} sx={{ color: '#94a3b8', textTransform: 'none', fontWeight: 700, mr: 2 }}>Cancel</Button>
                        <Button variant="contained" onClick={editingProduct ? handleUpdateProduct : handleAddProduct} sx={{ bgcolor: '#1e293b', color: 'white', borderRadius: 3, textTransform: 'none', px: 5, py: 1.2, fontWeight: 800, '&:hover': { bgcolor: '#000' } }}>{editingProduct ? 'Update Product' : 'Publish Product'}</Button>
                    </DialogActions>
                </Dialog>
            </Box>
        </Box>
    );
};

export default RetailManagement;

import React, { useEffect, useState } from 'react';
import {
    Box,
    Typography,
    Paper,
    Stack,
    List,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    IconButton,
    CircularProgress,
    Button,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField,
    MenuItem,
    InputAdornment,
    Grid
} from '@mui/material';
import { toast } from 'react-toastify';
import DashboardIcon from '@mui/icons-material/Dashboard';
import StoreIcon from '@mui/icons-material/Store';
import WarehouseIcon from '@mui/icons-material/Warehouse';
import FlashOnIcon from '@mui/icons-material/FlashOn';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import WorkOutlineIcon from '@mui/icons-material/WorkOutline';
import ExitToAppIcon from '@mui/icons-material/ExitToApp';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import SearchIcon from '@mui/icons-material/Search';
import { useNavigate } from 'react-router-dom';
import { WholesaleService, UploadService } from '../../../services/api';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';

const WholesaleManagement = () => {
    const navigate = useNavigate();
    const [products, setProducts] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Add Product State
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [newProduct, setNewProduct] = useState({
        title: '', pricePerUnit: '', minOrderQuantity: '', packSize: '', category: '', brand: '', stock: '', description: '', images: ''
    });
    const [isUploading, setIsUploading] = useState(false);

    // Mock search state
    const [searchQuery, setSearchQuery] = useState('');

    useEffect(() => {
        fetchProducts();
    }, []);

    const fetchProducts = async () => {
        try {
            const { data } = await WholesaleService.getAll();
            setProducts(data);
        } catch (error) {
            console.error("Failed to fetch wholesale products", error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        setIsUploading(true);
        try {
            const uploadPromises = Array.from(files).map(async (file) => {
                const { data } = await UploadService.uploadImage(file);
                return data.url;
            });

            const uploadedUrls = await Promise.all(uploadPromises);
            setNewProduct(prev => {
                const existingImages = prev.images ? prev.images.split(',').map(img => img.trim()).filter(img => img !== '') : [];
                const newImages = [...existingImages, ...uploadedUrls];
                return {
                    ...prev,
                    images: newImages.join(', ')
                };
            });
            toast.success(`${uploadedUrls.length} image(s) uploaded successfully!`);
        } catch (error) {
            console.error("Upload failed", error);
            toast.error('Upload failed');
        } finally {
            setIsUploading(false);
        }
    };

    const removeImage = (urlToRemove: string) => {
        setNewProduct(prev => {
            const currentImages = prev.images.split(',').map(img => img.trim()).filter(img => img !== '');
            const filteredImages = currentImages.filter(url => url !== urlToRemove);
            return {
                ...prev,
                images: filteredImages.join(', ')
            };
        });
    };

    const handleAddProduct = async () => {
        try {
            const productData = {
                ...newProduct,
                pricePerUnit: Number(newProduct.pricePerUnit),
                minOrderQuantity: Number(newProduct.minOrderQuantity),
                stock: Number(newProduct.stock),
                images: newProduct.images.split(',').map(img => img.trim()).filter(img => img !== '')
            };
            const { data } = await WholesaleService.create(productData);
            setProducts([data, ...products]);
            setIsModalOpen(false);
            setNewProduct({ title: '', pricePerUnit: '', minOrderQuantity: '', packSize: '', category: '', brand: '', stock: '', description: '', images: '' });
            toast.success("Wholesale product created successfully!");
        } catch (error) {
            toast.error("Failed to create wholesale product");
        }
    };

    const menuItems = [
        { name: 'Overview', icon: <DashboardIcon sx={{ fontSize: 20 }} />, path: '/admin/dashboard' },
        { name: 'Retail', icon: <StoreIcon sx={{ fontSize: 20 }} />, path: '/admin/retail' },
        { name: 'Wholesale', icon: <WarehouseIcon sx={{ fontSize: 20 }} />, path: '/admin/wholesale', active: true },
        { name: 'Q-Commerce', icon: <FlashOnIcon sx={{ fontSize: 20 }} />, path: '/admin/quick' },
        { name: 'Resale', icon: <AutorenewIcon sx={{ fontSize: 20 }} />, path: '/admin/resale' },
        { name: 'Freelance', icon: <WorkOutlineIcon sx={{ fontSize: 20 }} />, path: '/admin/freelance' },
    ];

    return (
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'white' }}>
            {/* Sidebar */}
            <Box sx={{
                width: 260,
                bgcolor: 'white',
                borderRight: '1px solid #f1f5f9',
                p: 3,
                display: 'flex',
                flexDirection: 'column',
                height: '100vh',
                position: 'sticky',
                top: 0
            }}>
                <Stack direction="row" alignItems="center" spacing={1.5} sx={{ mb: 5, px: 1 }}>
                    <Box sx={{ bgcolor: 'black', p: 0.8, borderRadius: 1.5, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Box component="span" sx={{ color: 'white', fontWeight: 900, fontSize: '1.2rem', lineHeight: 1 }}>R</Box>
                    </Box>
                    <Typography variant="h6" sx={{ fontWeight: 800, fontSize: '1.25rem', color: '#1e293b' }}>retails</Typography>
                </Stack>

                <List disablePadding sx={{ flexGrow: 1 }}>
                    {menuItems.map((item) => (
                        <ListItemButton
                            key={item.name}
                            onClick={() => item.path !== '/admin/wholesale' && navigate(item.path)}
                            sx={{
                                mb: 1,
                                borderRadius: 3,
                                bgcolor: item.active ? '#CFE8EC' : 'transparent',
                                color: item.active ? '#1e293b' : '#64748b',
                                '&:hover': { bgcolor: item.active ? '#CFE8EC' : '#f8fafc' },
                                py: 1.2,
                                px: 2
                            }}
                        >
                            <ListItemIcon sx={{ minWidth: 35, color: item.active ? '#1e293b' : '#64748b' }}>
                                {item.icon}
                            </ListItemIcon>
                            <ListItemText
                                primary={item.name}
                                primaryTypographyProps={{ fontWeight: item.active ? 700 : 500, fontSize: '0.95rem' }}
                            />
                        </ListItemButton>
                    ))}
                </List>

                <Box sx={{ mt: 'auto', pt: 2 }}>
                    <Stack onClick={() => { localStorage.removeItem('token'); localStorage.removeItem('userRole'); navigate('/admin/login'); }} direction="row" alignItems="center" spacing={2} sx={{ px: 2, cursor: 'pointer', color: '#64748b', '&:hover': { color: '#ef4444' } }}>
                        <ExitToAppIcon sx={{ fontSize: 20 }} />
                        <Typography variant="body2" fontWeight={600}>Logout</Typography>
                    </Stack>
                </Box>
            </Box>

            {/* Main Content */}
            <Box sx={{ flexGrow: 1, p: 4, overflow: 'auto', bgcolor: '#fbfcfd' }}>
                {/* Header Section */}
                <Box sx={{ mb: 5 }}>
                    <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
                        <Box>
                            <Typography variant="h4" sx={{ fontWeight: 800, color: '#1e293b', mb: 0.5 }}>Wholesale Management</Typography>
                            <Typography variant="body2" sx={{ color: '#64748b', fontWeight: 500 }}>Track and manage your wholesale bulk ecosystem</Typography>
                        </Box>

                        <Stack direction="row" spacing={2} alignItems="center">

                            <Button
                                variant="contained"
                                onClick={() => setIsModalOpen(true)}
                                startIcon={<AddIcon />}
                                sx={{
                                    bgcolor: '#CFE8EC',
                                    color: '#0e172a',
                                    borderRadius: 3,
                                    px: 3,
                                    py: 1,
