                            />

                            <IconButton
                                sx={{ position: 'absolute', bottom: 24, right: 24, bgcolor: 'white', ml: 'auto', width: 44, height: 44, boxShadow: '0 4px 12px rgba(0,0,0,0.05)', '&:hover': { bgcolor: '#f8fafc' } }}
                            >
                                <CameraAltOutlinedIcon sx={{ color: 'black' }} />
                            </IconButton>
                        </Box>
                    </Box>
                </Box>

                <Divider sx={{ mb: 8, borderColor: '#f1f5f9' }} />

                {/* Reviews Section */}
                <Box>
                    <ProductReviews
                        productId={product._id}
                        reviews={product.reviews || []}
                        averageRating={product.rating || 0}
                        totalReviews={product.numReviews || 0}
                        onReviewAdded={handleReviewAdded}
                    />
                </Box>
            </Container>

            <Footer />
        </Box>
    );
};

export default ProductDetails;

import { Box, Typography, Stack, Rating, TextField, Button, Avatar, Divider, Paper, IconButton } from '@mui/material';
import CameraAltOutlinedIcon from '@mui/icons-material/CameraAltOutlined';
import { useState } from 'react';
import { toast } from 'react-toastify';
import { ProductService } from '../../../services/api';

interface Review {
    _id: string;
    userName: string;
    rating: number;
    comment: string;
    createdAt: string;
}

interface ProductReviewsProps {
    productId: string;
    reviews: Review[];
    averageRating: number;
    totalReviews: number;
    onReviewAdded: () => void;
}

const ProductReviews = ({ productId, reviews, averageRating, totalReviews, onReviewAdded }: ProductReviewsProps) => {
    const [comment, setComment] = useState('');
    const [rating, setRating] = useState<number | null>(5);
    const [selectedImage, setSelectedImage] = useState<string | null>(null);

    const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setSelectedImage(reader.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleSubmit = async () => {
        if (!rating) {
            toast.error('Please select a rating');
            return;
        }
        if (!comment.trim()) {
            toast.error('Please enter a comment');
            return;
        }

        setIsSubmitting(true);
        try {
            await ProductService.createReview(productId, { rating, comment });
            toast.success('Review submitted successfully!');
            setComment('');
            setRating(5);
            onReviewAdded();
        } catch (error: any) {
            toast.error(error.response?.data?.message || 'Failed to submit review. Are you logged in?');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Box sx={{ mt: 8 }}>
            <Typography variant="h5" sx={{ fontWeight: 900, mb: 6, color: '#1a202c' }}>
                CUSTOMER REVIEWS ({totalReviews})
            </Typography>

            <Stack direction={{ xs: 'column', md: 'row' }} spacing={8} alignItems="flex-start">
                {/* Review Stats */}
                <Box sx={{ width: { xs: '100%', md: '300px' } }}>
                    <Box sx={{
                        p: 6,
                        bgcolor: '#f8fafc',
                        borderRadius: 4,
                        textAlign: 'center',
                        border: '1px solid #f1f5f9'
                    }}>
                        <Typography variant="h1" sx={{ fontWeight: 900, mb: 1, color: '#1a202c', fontSize: '4.5rem' }}>
                            {averageRating.toFixed(1)}
                        </Typography>
                        <Rating value={averageRating} readOnly precision={0.1} sx={{ color: '#fbbf24', mb: 1.5, fontSize: '1.5rem' }} />
                        <Typography variant="body2" sx={{ color: '#64748b', fontWeight: 700, textTransform: 'uppercase', letterSpacing: 0.5 }}>
                            Based on {totalReviews} reviews
                        </Typography>
                    </Box>

                    {/* Simple Message if no reviews */}
                    {reviews.length === 0 && (
                        <Typography sx={{ mt: 4, color: '#94a3b8', fontStyle: 'italic', textAlign: 'center' }}>
                            No reviews yet. Be the first to review!
                        </Typography>
                    )}
                </Box>

                {/* Right Side: Review Form & List */}
                <Box sx={{ flex: 1, width: '100%' }}>
                    <Paper
                        elevation={0}
                        sx={{
                            p: 4,
                            border: '1px solid #f1f5f9',
                            borderRadius: 4,
                            bgcolor: 'white',
                            mb: 8,
                            boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.05)'
                        }}
                    >
                        <Typography variant="h6" sx={{ fontWeight: 900, mb: 4, color: '#1a202c' }}>WRITE A REVIEW</Typography>
                        <Stack spacing={4}>
                            <Box>
                                <Typography variant="caption" sx={{ fontWeight: 800, display: 'block', mb: 1.5, color: '#94a3b8' }}>RATING</Typography>
                                <Rating
                                    value={rating}
                                    onChange={(_event, newValue) => setRating(newValue)}
                                    sx={{ color: '#fbbf24', fontSize: '2rem' }}
                                />
                            </Box>
                            <Box sx={{ position: 'relative' }}>
                                <Typography variant="caption" sx={{ fontWeight: 800, display: 'block', mb: 1.5, color: '#94a3b8' }}>YOUR COMMENT</Typography>
                                <TextField
                                    fullWidth
                                    multiline
                                    rows={4}
                                    placeholder="Share your thoughts about this product..."
                                    value={comment}
                                    onChange={(e) => setComment(e.target.value)}
                                    sx={{
                                        '& .MuiOutlinedInput-root': {
                                            borderRadius: 3,
                                            bgcolor: '#f8fafc',
                                            pb: 6, // Space for the image preview
                                            '& fieldset': { borderColor: '#f1f5f9' },
                                            '&:hover fieldset': { borderColor: '#e2e8f0' },
                                        }
                                    }}
                                />

                                {/* Photo Upload Logic */}
                                <Box sx={{ position: 'absolute', bottom: 12, right: 12, display: 'flex', alignItems: 'center', gap: 2 }}>
                                    {selectedImage && (
                                        <Box
                                            component="img"
                                            src={selectedImage}
                                            alt="Review Preview"
                                            sx={{ width: 40, height: 40, borderRadius: 2, objectFit: 'cover', border: '1px solid #e2e8f0' }}
                                        />
                                    )}
                                    <input
                                        accept="image/*"
                                        style={{ display: 'none' }}
                                        id="icon-button-file"
                                        type="file"
                                        onChange={handleImageUpload}
                                    />
                                    <label htmlFor="icon-button-file">
                                        <IconButton color="primary" aria-label="upload picture" component="span" sx={{ color: '#64748b' }}>
                                            <CameraAltOutlinedIcon />
                                        </IconButton>
                                    </label>
                                </Box>
                            </Box>
                            <Button
                                variant="contained"
                                fullWidth
                                onClick={handleSubmit}
                                disabled={isSubmitting}
                                sx={{
                                    bgcolor: 'black',
                                    color: 'white',
                                    py: 2,
                                    borderRadius: 3,
                                    fontWeight: 900,
                                    fontSize: '1rem',
                                    '&:hover': { bgcolor: '#1a1a1a' }
                                }}
                            >
                                {isSubmitting ? 'SUBMITTING...' : 'SUBMIT REVIEW'}
                            </Button>
                        </Stack>
                    </Paper>

                    {/* Reviews List */}
                    <Stack spacing={6}>
                        {reviews.map((review) => (
                            <Box key={review._id}>
                                <Stack direction="row" spacing={3} sx={{ mb: 2 }} alignItems="center">
                                    <Avatar sx={{
                                        bgcolor: '#f1f5f9',
                                        color: '#1a202c',
                                        fontWeight: 800,
                                        width: 50,
                                        height: 50
                                    }}>
                                        {review.userName?.[0] || 'U'}
                                    </Avatar>
                                    <Box sx={{ flex: 1 }}>
                                        <Typography variant="subtitle1" sx={{ fontWeight: 900, color: '#1a202c' }}>{review.userName}</Typography>
                                        <Rating value={review.rating} readOnly size="small" sx={{ color: '#fbbf24' }} />
                                    </Box>
                                    <Typography variant="caption" sx={{ color: '#94a3b8', fontWeight: 600 }}>
                                        {new Date(review.createdAt).toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' })}
                                    </Typography>
                                </Stack>
                                <Typography sx={{ color: '#4a5568', lineHeight: 1.8, pl: { md: 9 } }}>
                                    {review.comment}
                                </Typography>
                                <Divider sx={{ mt: 5, borderColor: '#f1f5f9' }} />
                            </Box>
                        ))}
                    </Stack>
                </Box>
            </Stack>
        </Box>
    );
};

export default ProductReviews;

import { useState, useEffect } from 'react';
import { Box, Typography, Stack, Tab, Tabs, CircularProgress, Card, CardMedia, CardContent, IconButton, Tooltip, Chip } from '@mui/material';
import { useNavigate, useSearchParams } from 'react-router-dom';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';
import ShoppingCartOutlinedIcon from '@mui/icons-material/ShoppingCartOutlined';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import CameraAltOutlinedIcon from '@mui/icons-material/CameraAltOutlined';
import { ProductService, WishlistService, CartService } from '../../../services/api';
import { toast } from 'react-toastify';

const Products = () => {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const searchQuery = searchParams.get('search');

    const [products, setProducts] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedTab, setSelectedTab] = useState('All');

    const categoriesList = ['All', 'Electronics', 'Lifestyle', 'Fashion'];
    const bgColors = ['#EAE0D5', '#F3E5D8', '#F8DEC8', '#F1F5F9', '#E2E8F0', '#E7E5E4', '#D6D3D1', '#F5E6D3'];

    useEffect(() => {
        if (searchQuery && selectedTab !== 'All') {
            setSelectedTab('All');
        } else {
            fetchProducts();
        }
    }, [selectedTab, searchQuery]);

    const fetchProducts = async () => {
        setLoading(true);
        try {
            const params: any = { limit: 8 };
            if (selectedTab !== 'All') {
                params.category = selectedTab;
            }
            if (searchQuery) {
                params.keyword = searchQuery;
            }
            const { data } = await ProductService.getAll(params);
            if (data.products) setProducts(data.products);
            else if (Array.isArray(data)) setProducts(data);
        } catch (error) {
            console.error("Error fetching products:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleTabChange = (_event: React.SyntheticEvent, newValue: string) => {
        setSelectedTab(newValue);
        if (searchQuery) {
            navigate('/retail');
        }
    };

    const handleAddToWishlist = async (e: React.MouseEvent, productId: string) => {
        e.stopPropagation();
        try {
            await WishlistService.addToWishlist({ productId });
            toast.success("Added to wishlist");
        } catch (error) {
            toast.error("Please login to add to wishlist");
        }
    };

    const handleAddToCart = async (e: React.MouseEvent, productId: string) => {
        e.stopPropagation();
        try {
            await CartService.addToCart({ productId, quantity: 1, type: 'Retail' });
            toast.success("Added to cart");
        } catch (error) {
            toast.error("Please login to add to cart");
        }
    };

    const getRandomBadge = (index: number) => {
        const badges = ["GOOD", "LIST NEW", "EXCELLENT", "PREMIUM"];
        return badges[index % badges.length];
    };

    return (
        <Box>
            {/* Featured Products Tabbed Section Header */}
            <Box sx={{ mt: 10, mb: 6 }}>
                <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" alignItems="flex-end" spacing={2} sx={{ mb: 4 }}>
                    <Typography variant="h3" sx={{ fontWeight: 900, textTransform: 'uppercase', letterSpacing: -1, fontFamily: 'sans-serif' }}>
                        Featured Products
                    </Typography>

                    <Tabs
                        value={selectedTab}
                        onChange={handleTabChange}
                        textColor="inherit"
                        sx={{
                            '& .MuiTabs-indicator': { bgcolor: 'black', height: 3 },
                            '& .MuiTab-root': {
                                textTransform: 'uppercase',
                                fontWeight: 700,
                                color: '#94a3b8',
                                fontSize: '0.9rem',
                                letterSpacing: 1,
                                minWidth: 'auto',
                                mx: 1.5,
                                pb: 1.5,
                                '&.Mui-selected': { color: 'black' }
                            }
                        }}
                    >
                        {categoriesList.map((cat) => (
                            <Tab key={cat} label={cat} value={cat} />
                        ))}
                    </Tabs>
                </Stack>
            </Box>

            {/* Products Grid */}
            {loading ? (
                <Box sx={{ display: 'flex', justifyContent: 'center', py: 10 }}>
                    <CircularProgress sx={{ color: 'black' }} />
                </Box>
            ) : (
                <Box sx={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
                    gap: 3,
                }}>
                    {products.map((product, index) => (
                        <Card
                            key={product._id}
                            elevation={0}
                            onClick={() => navigate(`/product/${product._id}`)}
                            sx={{
                                cursor: 'pointer',
                                borderRadius: 4,
                                border: '1px solid #f3f4f6',
                                overflow: 'visible',
                                transition: 'all 0.3s ease',
                                '&:hover': {
                                    transform: 'translateY(-8px)',
                                    boxShadow: '0 12px 24px -10px rgba(0,0,0,0.1)'
                                }
                            }}
                        >
                            {/* Image Container */}
                            <Box
                                className="product-card-bg"
                                sx={{
                                    height: 320, // Slightly reduced height from 340 for better ratio with new width
                                    bgcolor: bgColors[index % bgColors.length],
                                    borderRadius: 4,
                                    position: 'relative',
                                    overflow: 'hidden',
                                    mb: 2,
                                    '&:hover .action-buttons': { opacity: 1, transform: 'translateY(0)' }
                                }}
                            >
                                {/* Badge */}
                                <Chip
                                    label={getRandomBadge(index)}
                                    size="small"
                                    sx={{
                                        position: 'absolute',
                                        top: 12,
                                        left: 12,
                                        bgcolor: 'rgba(255,255,255,0.9)',
                                        borderRadius: 1,
                                        fontSize: '0.65rem',
                                        fontWeight: 800,
                                        height: 20,
                                        zIndex: 2,
                                        backdropFilter: 'blur(4px)'
                                    }}
                                />

                                <CardMedia
                                    component="img"
                                    image={product.images?.[0] || product.thumbnail || 'https://via.placeholder.com/300'}
                                    alt={product.title}
                                    sx={{
                                        width: '100%',
                                        height: '100%',
                                        objectFit: 'cover',
                                        objectPosition: 'top center',
                                        transition: 'transform 0.5s ease',
                                        '&:hover': { transform: 'scale(1.05)' }
                                    }}
                                />

                                {/* Old Style Overlay Buttons */}
                                <Box
                                    className="action-buttons"
                                    sx={{
                                        position: 'absolute',
                                        bottom: 15,
                                        right: 15,
                                        display: 'flex',
                                        gap: 1,
                                        opacity: 0,
                                        transform: 'translateY(10px)',
                                        transition: 'all 0.3s ease',
                                        zIndex: 2
                                    }}
                                >
                                    <Tooltip title="Visual Search" arrow>
                                        <IconButton
                                            sx={{
                                                bgcolor: 'white', color: 'black', width: 40, height: 40,
                                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                                                '&:hover': { bgcolor: 'black', color: 'white' }
                                            }}
                                        >
                                            <CameraAltOutlinedIcon fontSize="small" />
                                        </IconButton>
                                    </Tooltip>
                                    <Tooltip title="Add to Cart" arrow>
                                        <IconButton
                                            onClick={(e) => handleAddToCart(e, product._id)}
                                            sx={{
                                                bgcolor: 'white', color: 'black', width: 40, height: 40,
                                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                                                '&:hover': { bgcolor: 'black', color: 'white' }
                                            }}
                                        >
                                            <ShoppingCartOutlinedIcon fontSize="small" />
                                        </IconButton>
                                    </Tooltip>
                                    <Tooltip title="Wishlist" arrow>
                                        <IconButton
                                            onClick={(e) => handleAddToWishlist(e, product._id)}
                                            sx={{
                                                bgcolor: 'white', color: 'black', width: 40, height: 40,
                                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                                                '&:hover': { bgcolor: '#ef4444', color: 'white' }
                                            }}
                                        >
                                            <FavoriteBorderIcon fontSize="small" />
                                        </IconButton>
                                    </Tooltip>
                                </Box>
                            </Box>

                            {/* Content */}
                            <CardContent sx={{ p: 1 }}>
                                <Typography
                                    variant="subtitle1"
                                    sx={{
                                        fontWeight: 800,
                                        mb: 0.5,
                                        color: '#1e293b',
                                        overflow: 'hidden',
                                        textOverflow: 'ellipsis',
                                        whiteSpace: 'nowrap'
                                    }}
                                >
                                    {product.title}
                                </Typography>

                                {/* Location Line */}
                                <Stack direction="row" alignItems="center" spacing={0.5} sx={{ mb: 1 }}>
                                    <LocationOnIcon sx={{ fontSize: 14, color: '#f43f5e' }} />
                                    <Typography variant="caption" sx={{ color: '#64748b', fontWeight: 600 }}>
                                        {product.location || 'Global Shipping'}
                                    </Typography>
                                </Stack>

                                <Typography variant="h6" sx={{ fontWeight: 900, color: '#0f172a' }}>
                                    Ôé╣{(Number(product?.price ?? product?.pricePerUnit ?? 0) || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                                </Typography>
                            </CardContent>
                        </Card>
                    ))}
                </Box>
            )}
        </Box>
    );
};

export default Products;

import { useState, useEffect } from 'react';
import {
    Box,
    Container,
    Typography,
    Button,
    Divider,
    Stack,
    Paper,
    Avatar,
    Chip,
    IconButton
} from '@mui/material';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import VerifiedUserIcon from '@mui/icons-material/VerifiedUser';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';
import FavoriteIcon from '@mui/icons-material/Favorite';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import Navbar from '../../../WrapperComponents/Navbar';
import Footer from '../../../WrapperComponents/Footer';
import { ResaleService, WishlistService } from '../../../../services/api';
import { toast } from 'react-toastify';

const ResaleProductDetails = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const location = useLocation();
    const [selectedImage, setSelectedImage] = useState(0);
    const [isFavorite, setIsFavorite] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [fetchedProduct, setFetchedProduct] = useState<any>(null);

    // Fallback Mock Data
    const defaultProducts = [
        {
            _id: 'mock1',
            id: 1,
            title: "iPhone 13 Pro, 256GB",
            price: "599",
            condition: "CERTIFIED REFURBISHED",
            location: "San Francisco, CA",
            image: "https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=400&q=80",
            images: ["https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=400&q=80"],
            tagColor: "#bef264",
            description: "Pristine condition iPhone 13 Pro. Battery health 98%. Comes with original box and cable. No scratches or dents.",
            seller: "TechResale Pro"
        },
        {
            _id: 'mock2',
            id: 2,
            title: "Herman Miller Aeron",
            price: "850",
            condition: "LIKE NEW",
            location: "Austin, TX",
            image: "https://images.unsplash.com/photo-1505843490538-5133c6c7d0e1?auto=format&fit=crop&w=400&q=80",
            images: ["https://images.unsplash.com/photo-1505843490538-5133c6c7d0e1?auto=format&fit=crop&w=400&q=80"],
            tagColor: "#f1f5f9",
            description: "Fully loaded Herman Miller Aeron size B. PostureFit SL, tilt limiter, fully adjustable arms. Manufactured 2023.",
            seller: "Office Furniture Oulet"
        }
    ];

    useEffect(() => {
        const load = async () => {
            if (!id) return;
            try {
                const { data } = await ResaleService.getById(id);
                setFetchedProduct(data);
            } catch (error) {
                console.error("Error fetching resale product", error);
            } finally {
                setIsLoading(false);
            }
        };
        load();
    }, [id]);

    const product = fetchedProduct || location.state?.product || defaultProducts.find(p => p.id === Number(id));

    const handleToggleWishlist = async () => {
        if (!product?._id) {
            toast.error('Product ID not available.');
            return;
        }
        try {
            if (isFavorite) {
                await WishlistService.removeFromWishlist(product._id);
                setIsFavorite(false);
                toast.success('Removed from wishlist');
            } else {
                await WishlistService.addToWishlist({
                    productId: product._id,
                    type: 'resale'
                });
                setIsFavorite(true);
                toast.success('Added to wishlist!');
            }
        } catch (error) {
            console.error(error);
            toast.error('Please login to manage wishlist');
        }
    };

    if (isLoading && !product) {
        return (
            <Box sx={{ bgcolor: 'white', minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Typography>Loading...</Typography>
            </Box>
        );
    }

    if (!product) {
        return (
            <Box sx={{ bgcolor: 'white', minHeight: '100vh' }}>
                <Navbar />
                <Container maxWidth="xl" sx={{ mt: 4, mb: 8, textAlign: 'center' }}>
                    <Typography variant="h4">Product not found</Typography>
                    <Button onClick={() => navigate('/resale')} sx={{ mt: 2 }}>Back to Resale</Button>
                </Container>
                <Footer />
            </Box>
        );
    }

    const productImages = product.images && product.images.length > 0 ? product.images : [product.image];

    return (
        <Box sx={{ bgcolor: '#f8fafc', minHeight: '100vh' }}>
            <Navbar />
            <Container maxWidth="xl" sx={{ mt: 4, mb: 8 }}>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                    <Box sx={{ width: { xs: '100%', md: '58%' } }}>
                        <Paper elevation={0} sx={{ p: 2, borderRadius: 3, bgcolor: 'white', mb: 2 }}>
                            <Box sx={{ height: '500px', display: 'flex', justifyContent: 'center', alignItems: 'center', bgcolor: '#f1f5f9', borderRadius: 2, mb: 2, overflow: 'hidden', position: 'relative' }}>
                                <img src={productImages[selectedImage]} alt={product.title} style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }} />
                                <IconButton
                                    onClick={handleToggleWishlist}
                                    sx={{ position: 'absolute', top: 20, right: 20, bgcolor: 'white', p: 1.5, boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', '&:hover': { bgcolor: '#f8fafc' } }}
                                >
                                    {isFavorite ? <FavoriteIcon sx={{ color: '#ef4444' }} /> : <FavoriteBorderIcon />}
                                </IconButton>
                            </Box>
                            <Stack direction="row" spacing={2} sx={{ overflowX: 'auto', py: 1 }}>
                                {productImages.map((img: string, index: number) => (
                                    <Box key={index} onMouseEnter={() => setSelectedImage(index)} sx={{ width: 80, height: 80, flexShrink: 0, border: `2px solid ${selectedImage === index ? '#2563eb' : 'transparent'}`, borderRadius: 2, cursor: 'pointer', overflow: 'hidden' }}>
                                        <img src={img} alt={`thumb-${index}`} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                    </Box>
                                ))}
                            </Stack>
                        </Paper>
                        <Paper elevation={0} sx={{ p: 4, borderRadius: 3, bgcolor: 'white' }}>
                            <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>Description</Typography>
                            <Typography variant="body1" sx={{ color: '#475569', lineHeight: 1.7 }}>{product.description || "No detailed description provided by the seller."}</Typography>
                        </Paper>
                    </Box>
                    <Box sx={{ width: { xs: '100%', md: '38%' } }}>
                        <Paper elevation={0} sx={{ p: 4, borderRadius: 3, bgcolor: 'white', height: '100%' }}>
                            <Chip label={product.condition} sx={{ bgcolor: product.tagColor || '#e2e8f0', color: '#0f172a', fontWeight: 700, mb: 2 }} />
                            <Typography variant="h4" component="h1" gutterBottom sx={{ fontWeight: 800, color: '#0f172a' }}>{product.title}</Typography>
                            <Typography variant="h3" sx={{ fontWeight: 800, color: '#2563eb', mb: 3 }}>Ôé╣{product.price}</Typography>
                            <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 4 }}><LocationOnIcon sx={{ color: '#64748b' }} /><Typography variant="body1" sx={{ color: '#64748b', fontWeight: 500 }}>{product.location}</Typography></Stack>
                            <Divider sx={{ my: 3 }} />
                            <Box sx={{ mb: 4 }}>
                                <Typography variant="subtitle2" sx={{ color: '#64748b', mb: 1 }}>Seller</Typography>
                                <Stack direction="row" alignItems="center" spacing={2}>
                                    <Avatar sx={{ bgcolor: '#2563eb', width: 48, height: 48 }}>{product.sellerName?.[0] || (typeof product.seller === 'string' ? product.seller[0] : (product.seller?.username?.[0] || 'S'))}</Avatar>
                                    <Box><Typography variant="subtitle1" sx={{ fontWeight: 700 }}>{product.sellerName || (typeof product.seller === 'string' ? product.seller : (product.seller?.username || "Verified Seller"))}</Typography><Stack direction="row" alignItems="center" spacing={0.5}><VerifiedUserIcon sx={{ fontSize: 16, color: '#10b981' }} /><Typography variant="caption" sx={{ color: '#10b981', fontWeight: 600 }}>Identity Verified</Typography></Stack></Box>
                                </Stack>
                            </Box>
                            <Stack spacing={2}>
                                <Button variant="contained" fullWidth size="large" startIcon={<WhatsAppIcon />} sx={{ bgcolor: '#25d366', color: 'white', py: 1.5, fontWeight: 700, fontSize: '1.1rem', textTransform: 'none', '&:hover': { bgcolor: '#128c7e' } }}>Chat on WhatsApp</Button>
                                <Button variant="outlined" fullWidth size="large" sx={{ py: 1.5, color: '#0f172a', borderColor: '#cbd5e1', fontWeight: 700, textTransform: 'none', '&:hover': { bgcolor: '#f1f5f9', borderColor: '#94a3b8' } }}>Make an Offer</Button>
                            </Stack>
                            <Box sx={{ mt: 4, p: 2, bgcolor: '#eff6ff', borderRadius: 2 }}><Typography variant="subtitle2" sx={{ fontWeight: 700, color: '#1e40af', mb: 1 }}>Is this item still available?</Typography><Typography variant="body2" sx={{ color: '#1e3a8a' }}>Send a message to the seller to confirm availability and arrange a meetup.</Typography></Box>
                        </Paper>
                    </Box>
                </Box>
            </Container>
            <Footer />
        </Box>
    );
};

export default ResaleProductDetails;

import { useState } from 'react';
import { Box, Button, Dialog, DialogTitle, DialogContent, DialogActions, TextField, Typography, Stack, CircularProgress, Alert } from '@mui/material';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';
import ImageOutlinedIcon from '@mui/icons-material/ImageOutlined';

interface BuyerRequestModalProps {
    open: boolean;
    onClose: () => void;
    onSubmit: (request: any) => void;
}

const BuyerRequestModal = ({ open, onClose, onSubmit }: BuyerRequestModalProps) => {
    const [step, setStep] = useState(1); // 1: Generate Image, 2: Details
    const [prompt, setPrompt] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);
    const [generatedImage, setGeneratedImage] = useState<string | null>(null);

    const [details, setDetails] = useState({
        name: '',
        productName: '',
        number: '',
        email: '',
        location: ''
    });

    const handleGenerate = async () => {
        if (!prompt) return;
        setIsGenerating(true);

        try {
            console.log('Generating image with prompt:', prompt);

            // Using the provided API key (Freepik)
            const API_KEY = "FPSX9eeb26f1be1427e9773dfd2d7e3f4447";

            console.log('Using Freepik Proxy...');
            const response = await fetch('/freepik-api/v1/ai/text-to-image', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-freepik-api-key': API_KEY,
                    'Accept': 'application/json'
                },
                body: JSON.stringify({
                    prompt: prompt,
                    aspect_ratio: "square",
                    num_images: 1
                })
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}));
                console.error('API Error Details:', errorData);
                throw new Error(`API request failed with status ${response.status}: ${errorData.message || response.statusText}`);
            }

            const data = await response.json();

            let imageUrl = null;
            if (data.data && data.data.length > 0) {
                if (data.data[0].base64) {
                    imageUrl = `data:image/png;base64,${data.data[0].base64}`;
                } else if (data.data[0].url) {
                    imageUrl = data.data[0].url;
                }
            }
            if (!imageUrl && data.url) imageUrl = data.url;

            if (!imageUrl) throw new Error('Could not parse image URL from response');

            setGeneratedImage(imageUrl);
            setStep(2); // Move to details step

        } catch (error: any) {
            console.error('Error generating image:', error);
            alert(`Failed to generate image: ${error.message}\n\nIf you see a CORS error, please RESTART your development server (npm run dev).`);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleSubmit = () => {
        const newRequest = {
            id: Date.now(),
            image: generatedImage,
            name: details.name,
            productType: details.productName,
            phoneNumber: details.number,
            email: details.email,
            location: details.location,
            status: 'Pending',
            date: new Date().toLocaleDateString()
        };
        onSubmit(newRequest);
        handleClose();
    };

    const handleClose = () => {
        onClose();
        // Reset state
        setStep(1);
        setPrompt('');
        setGeneratedImage(null);
        setDetails({ name: '', productName: '', number: '', email: '', location: '' });
    };

    return (
        <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth PaperProps={{ sx: { borderRadius: 3 } }}>
            <DialogTitle sx={{ fontWeight: 800 }}>
                {step === 1 ? 'Generate Product Image' : 'Request Details'}
            </DialogTitle>
            <DialogContent dividers>
                {step === 1 ? (
                    <Stack spacing={3}>
                        <Alert severity="info" icon={<AutoAwesomeIcon />}>
                            Describe the product you are looking for, and our AI will generate a visualization for sellers.
                        </Alert>
                        <TextField
                            label="Product Description"
                            multiline
                            rows={3}
                            placeholder="e.g. Heavy duty steel pipes for industrial construction..."
                            fullWidth
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                        />
                        <Box sx={{ display: 'flex', justifyContent: 'center', minHeight: 200, bgcolor: '#f5f5f5', borderRadius: 2, alignItems: 'center', border: '1px dashed #ccc' }}>
                            {isGenerating ? (
                                <CircularProgress />
                            ) : generatedImage ? (
                                <Box component="img" src={generatedImage} sx={{ maxWidth: '100%', maxHeight: 200 }} />
                            ) : (
                                <Stack alignItems="center" color="text.secondary">
                                    <ImageOutlinedIcon sx={{ fontSize: 40, mb: 1 }} />
                                    <Typography variant="caption">Preview will appear here</Typography>
                                </Stack>
                            )}
                        </Box>
                    </Stack>
                ) : (
                    <Stack spacing={2}>
                        {generatedImage && (
                            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
                                <Box component="img" src={generatedImage} sx={{ width: 100, height: 100, borderRadius: 2, objectFit: 'cover' }} />
                            </Box>
                        )}
                        <TextField
                            label="Your Name"
                            fullWidth
                            value={details.name}
                            onChange={(e) => setDetails({ ...details, name: e.target.value })}
                        />
                        <TextField
                            label="Product Type"
                            fullWidth
                            value={details.productName}
                            onChange={(e) => setDetails({ ...details, productName: e.target.value })}
                        />
                        <TextField
                            label="Phone Number"
                            fullWidth
                            value={details.number}
                            onChange={(e) => setDetails({ ...details, number: e.target.value })}
                        />
                        <TextField
                            label="Email Address"
                            fullWidth
                            value={details.email}
                            onChange={(e) => setDetails({ ...details, email: e.target.value })}
                        />
                        <TextField
                            label="Location"
                            fullWidth
                            value={details.location}
                            onChange={(e) => setDetails({ ...details, location: e.target.value })}
                        />
                    </Stack>
                )}
            </DialogContent>
            <DialogActions sx={{ p: 2.5 }}>
                <Button onClick={handleClose} color="inherit">Cancel</Button>
                {step === 1 ? (
                    <Button
                        onClick={handleGenerate}
                        variant="contained"
                        disabled={!prompt || isGenerating}
                        startIcon={isGenerating ? <CircularProgress size={20} color="inherit" /> : <AutoAwesomeIcon />}
                        sx={{ bgcolor: 'black', '&:hover': { bgcolor: '#333' } }}
                    >
                        {isGenerating ? 'Generating...' : 'Generate & Continue'}
                    </Button>
                ) : (
                    <Button
                        onClick={handleSubmit}
                        variant="contained"
                        disabled={!details.name || !details.productName || !details.number}
                        sx={{ bgcolor: '#bef264', color: 'black', fontWeight: 700, '&:hover': { bgcolor: '#a3e635' } }}
                    >
                        Post Request
                    </Button>
                )}
            </DialogActions>
        </Dialog>
    );
};

export default BuyerRequestModal;

