import { useEffect, useState } from 'react';
import { Box, Typography, Paper, Chip, Button } from '@mui/material';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import PhoneIcon from '@mui/icons-material/Phone';
import EmailIcon from '@mui/icons-material/Email';

const BuyerRequestsFeed = () => {
    const [requests, setRequests] = useState<any[]>([]);

    useEffect(() => {
        const storedRequests = localStorage.getItem('wholesale_requests');
        if (storedRequests) {
            setRequests(JSON.parse(storedRequests).reverse());
        }
    }, []);

    if (requests.length === 0) {
        return (
            <Box sx={{ p: 4, textAlign: 'center', color: '#64748b' }}>
                <Typography>No buyer requests found yet.</Typography>
            </Box>
        );
    }

    return (
        <Box sx={{ mt: 3 }}>
            <Typography variant="h6" sx={{ fontWeight: 800, mb: 3 }}>Recent Buyer Requests</Typography>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                {requests.map((request) => (
                    <Paper
                        key={request.id}
                        elevation={0}
                        sx={{
                            p: 2,
                            borderRadius: 3,
                            border: '1px solid #e2e8f0',
                            display: 'flex',
                            gap: 2,
                            transition: 'all 0.3s',
                            '&:hover': {
                                boxShadow: '0 4px 20px rgba(0,0,0,0.05)',
                                borderColor: '#cbd5e1'
                            }
                        }}
                    >
                        {/* Left: Image */}
                        {request.image && (
                            <Box
                                component="img"
                                src={request.image}
                                sx={{
                                    width: 120,
                                    height: 120,
                                    objectFit: 'cover',
                                    borderRadius: 2,
                                    bgcolor: '#f1f5f9',
                                    flexShrink: 0
                                }}
                            />
                        )}

                        {/* Right: Content */}
                        <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                            {/* Title Row */}
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <Typography variant="h6" sx={{ fontWeight: 800, fontSize: '1.1rem' }}>
                                        {request.productType}
                                    </Typography>
                                    <Chip
                                        label="NEW"
                                        size="small"
                                        sx={{
                                            bgcolor: '#bef264',
                                            color: '#000',
