            {/* Content Container */}
            <Box sx={{ flex: 1, pl: { md: 4 }, pt: { xs: 3, md: 0 }, display: 'flex', flexDirection: 'column' }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1.5 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <BusinessIcon sx={{ color: '#cbd5e1', fontSize: 18 }} />
                        <Typography
                            variant="caption"
                            sx={{
                                fontWeight: 700,
                                color: '#94a3b8',
                                letterSpacing: 1.5,
                                textTransform: 'uppercase'
                            }}
                        >
                            {item.companyName || "XYZ INDUSTRIES"}
                        </Typography>
                    </Box>
                    {item.inStock !== false && (
                        <Chip
                            label="IN STOCK"
                            size="small"
                            sx={{
                                bgcolor: '#f0fff4',
                                color: '#38a169',
                                fontWeight: 800,
                                fontSize: '0.65rem',
                                height: '22px',
                                borderRadius: 1.5,
                                letterSpacing: 0.5
                            }}
                        />
                    )}
                </Box>

                <Typography
                    variant="h5"
                    sx={{
                        fontWeight: 800,
                        color: '#1a202c',
                        mb: 1.5,
                        lineHeight: 1.2,
                        fontSize: '1.5rem'
                    }}
                >
                    {item.title || "Modern Minimalist Photo Frame"}
                </Typography>

                <Typography
                    variant="body2"
                    sx={{
                        color: '#718096',
                        mb: 3,
