                {/* Action Buttons */}
                <Box sx={{ mt: 'auto', display: 'flex', alignItems: 'center', gap: 2 }}>
                    <Button
                        variant="contained"
                        startIcon={<PhoneIcon />}
                        sx={{
                            flex: 1,
